  1→package jlsm.table;
  2→
  3→import java.util.List;
  4→import java.util.Objects;
  5→
  6→/**
  7→ * Represents the type of a field in a {@link JlsmSchema}.
  8→ *
  9→ * <p>
 10→ * FieldType is a sealed interface with three permitted implementations:
 11→ * <ul>
 12→ * <li>{@link Primitive} — an enum of scalar types</li>
 13→ * <li>{@link ArrayType} — a homogeneous array of a given element type</li>
 14→ * <li>{@link ObjectType} — a nested object with its own field definitions</li>
 15→ * </ul>
 16→ */
 17→public sealed interface FieldType
 18→        permits FieldType.Primitive, FieldType.ArrayType, FieldType.ObjectType,
 19→        FieldType.VectorType {
 20→
 21→    /** Scalar primitive field types. */
 22→    enum Primitive implements FieldType {
 23→        STRING, INT8, INT16, INT32, INT64, FLOAT16, FLOAT32, FLOAT64, BOOLEAN, TIMESTAMP
 24→    }
 25→
 26→    /**
 27→     * A homogeneous array of elements, all sharing the same {@link FieldType}.
 28→     *
 29→     * @param elementType the type of each element in the array; must not be null
 30→     */
 31→    record ArrayType(FieldType elementType) implements FieldType {
 32→        public ArrayType {
 33→            Objects.requireNonNull(elementType, "elementType must not be null");
 34→        }
 35→    }
 36→
 37→    /**
 38→     * A nested object type with an ordered list of named fields.
 39→     *
 40→     * @param fields the field definitions of the nested object; must not be null
 41→     */
 42→    record ObjectType(List<FieldDefinition> fields) implements FieldType {
 43→        public ObjectType {
 44→            Objects.requireNonNull(fields, "fields must not be null");
 45→            fields = List.copyOf(fields);
 46→        }
 47→
 48→        /**
 49→         * Creates a {@link JlsmSchema} from this ObjectType's field definitions.
 50→         *
 51→         * @param name the schema name; must not be null
 52→         * @param version the schema version
 53→         * @return a new JlsmSchema with this ObjectType's fields
 54→         */
 55→        public JlsmSchema toSchema(String name, int version) {
 56→            Objects.requireNonNull(name, "name must not be null");
 57→            JlsmSchema.Builder builder = JlsmSchema.builder(name, version);
 58→            for (FieldDefinition fd : fields) {
 59→                builder.field(fd.name(), fd.type());
 60→            }
 61→            return builder.build();
 62→        }
 63→    }
 64→
 65→    /**
 66→     * A fixed-dimension vector of floating-point elements.
 67→     *
 68→     * @param elementType the element precision; must be {@link Primitive#FLOAT16} or
 69→     *            {@link Primitive#FLOAT32}
 70→     * @param dimensions the fixed number of elements per vector; must be positive
 71→     */
 72→    record VectorType(Primitive elementType, int dimensions) implements FieldType {
 73→        public VectorType {
 74→            Objects.requireNonNull(elementType, "elementType must not be null");
 75→            if (elementType != Primitive.FLOAT16 && elementType != Primitive.FLOAT32) {
 76→                throw new IllegalArgumentException(
 77→                        "VectorType elementType must be FLOAT16 or FLOAT32, got: " + elementType);
 78→            }
 79→            if (dimensions <= 0) {
 80→                throw new IllegalArgumentException(
 81→                        "VectorType dimensions must be positive, got: " + dimensions);
 82→            }
 83→        }
 84→    }
 85→
 86→    // --- Static factory shortcuts ---
 87→
 88→    /** Returns {@link Primitive#STRING}. */
 89→    static FieldType string() {
 90→        return Primitive.STRING;
 91→    }
 92→
 93→    /** Returns {@link Primitive#INT32}. */
 94→    static FieldType int32() {
 95→        return Primitive.INT32;
 96→    }
 97→
 98→    /** Returns {@link Primitive#INT64}. */
 99→    static FieldType int64() {
100→        return Primitive.INT64;
101→    }
102→
103→    /** Returns {@link Primitive#FLOAT32}. */
104→    static FieldType float32() {
105→        return Primitive.FLOAT32;
106→    }
107→
108→    /** Returns {@link Primitive#FLOAT64}. */
109→    static FieldType float64() {
110→        return Primitive.FLOAT64;
111→    }
112→
113→    /** Returns {@link Primitive#BOOLEAN}. */
114→    static FieldType boolean_() {
115→        return Primitive.BOOLEAN;
116→    }
117→
118→    /** Returns {@link Primitive#TIMESTAMP}. */
119→    static FieldType timestamp() {
120→        return Primitive.TIMESTAMP;
121→    }
122→
123→    /**
124→     * Returns a {@link VectorType} with the given element type and dimensions.
125→     *
126→     * @param elementType the element precision; must be FLOAT16 or FLOAT32
127→     * @param dimensions the fixed number of elements per vector; must be positive
128→     * @return a new VectorType
129→     */
130→    static FieldType vector(Primitive elementType, int dimensions) {
131→        return new VectorType(elementType, dimensions);
132→    }
133→
134→    /**
135→     * Returns an {@link ArrayType} with the given element type.
136→     *
137→     * @param elementType the element type; must not be null
138→     * @return a new ArrayType
139→     */
140→    static FieldType arrayOf(FieldType elementType) {
141→        assert elementType != null : "elementType must not be null";
142→        return new ArrayType(elementType);
143→    }
144→
145→    /**
146→     * Returns an {@link ObjectType} with the given field definitions.
147→     *
148→     * @param fields the field definitions; must not be null
149→     * @return a new ObjectType
150→     */
151→    static FieldType objectOf(List<FieldDefinition> fields) {
152→        assert fields != null : "fields must not be null";
153→        return new ObjectType(fields);
154→    }
155→}
