  1→package jlsm.table;
  2→
  3→import java.util.ArrayList;
  4→import java.util.HashMap;
  5→import java.util.List;
  6→import java.util.Map;
  7→import java.util.Objects;
  8→import java.util.function.Consumer;
  9→
 10→/**
 11→ * Describes the structure of documents stored in a {@link JlsmTable}.
 12→ *
 13→ * <p>
 14→ * A schema has a name, a version, an ordered list of {@link FieldDefinition}s, and a maximum
 15→ * nesting depth limit for object fields.
 16→ */
 17→public final class JlsmSchema {
 18→
 19→    private static final int DEFAULT_MAX_DEPTH = 10;
 20→    private static final int ABSOLUTE_MAX_DEPTH = 25;
 21→
 22→    private final String name;
 23→    private final int version;
 24→    private final List<FieldDefinition> fields;
 25→    private final int maxDepth;
 26→    private final Map<String, Integer> fieldIndexMap;
 27→
 28→    private JlsmSchema(String name, int version, List<FieldDefinition> fields, int maxDepth) {
 29→        assert name != null : "name must not be null";
 30→        assert fields != null : "fields must not be null";
 31→        assert maxDepth >= 0 && maxDepth <= ABSOLUTE_MAX_DEPTH : "maxDepth out of range";
 32→
 33→        this.name = name;
 34→        this.version = version;
 35→        this.fields = List.copyOf(fields);
 36→        this.maxDepth = maxDepth;
 37→
 38→        // Build field index map for O(1) lookup
 39→        final Map<String, Integer> indexMap = new HashMap<>(fields.size() * 2);
 40→        for (int i = 0; i < fields.size(); i++) {
 41→            indexMap.put(fields.get(i).name(), i);
 42→        }
 43→        this.fieldIndexMap = Map.copyOf(indexMap);
 44→    }
 45→
 46→    /** Returns the schema name. */
 47→    public String name() {
 48→        return name;
 49→    }
 50→
 51→    /** Returns the schema version. */
 52→    public int version() {
 53→        return version;
 54→    }
 55→
 56→    /** Returns an unmodifiable ordered list of field definitions. */
 57→    public List<FieldDefinition> fields() {
 58→        return fields;
 59→    }
 60→
 61→    /** Returns the maximum allowed nesting depth for object fields. */
 62→    public int maxDepth() {
 63→        return maxDepth;
 64→    }
 65→
 66→    /**
 67→     * Returns the zero-based index of the field with the given name, or {@code -1} if no such field
 68→     * exists.
 69→     *
 70→     * @param name the field name to look up; must not be null
 71→     * @return the field index, or -1 if not found
 72→     */
 73→    public int fieldIndex(String name) {
 74→        Objects.requireNonNull(name, "name must not be null");
 75→        assert name != null : "name must not be null";
 76→        return fieldIndexMap.getOrDefault(name, -1);
 77→    }
 78→
 79→    /**
 80→     * Creates a new {@link Builder} for a schema with the given name and version.
 81→     *
 82→     * @param name the schema name; must not be null
 83→     * @param version the schema version
 84→     * @return a new Builder
 85→     */
 86→    public static Builder builder(String name, int version) {
 87→        Objects.requireNonNull(name, "name must not be null");
 88→        return new Builder(name, version, 0, DEFAULT_MAX_DEPTH, null);
 89→    }
 90→
 91→    /**
 92→     * Builder for {@link JlsmSchema}.
 93→     *
 94→     * <p>
 95→     * The builder tracks a current nesting depth; {@link #objectField} creates a nested builder at
 96→     * {@code depth + 1}. {@link #build()} validates that no level exceeds the configured
 97→     * {@code maxDepth}.
 98→     */
 99→    public static final class Builder {
100→
101→        private final String name;
102→        private final int version;
103→        private final int currentDepth;
104→        private final List<FieldDefinition> fields = new ArrayList<>();
105→
106→        // maxDepth is tracked on the root builder; nested builders reference the root
107→        private int maxDepth;
108→        // parentBuilder is null for the root; non-null for nested builders
109→        private final Builder rootBuilder;
110→
111→        private Builder(String name, int version, int currentDepth, int maxDepth,
112→                Builder rootBuilder) {
113→            this.name = name;
114→            this.version = version;
115→            this.currentDepth = currentDepth;
116→            this.maxDepth = maxDepth;
117→            this.rootBuilder = rootBuilder;
118→        }
119→
120→        /**
121→         * Adds a primitive or array field to this schema level.
122→         *
123→         * @param name the field name; must not be null
124→         * @param type the field type; must not be null
125→         * @return this builder
126→         */
127→        public Builder field(String name, FieldType type) {
128→            Objects.requireNonNull(name, "name must not be null");
129→            Objects.requireNonNull(type, "type must not be null");
130→            assert name != null : "name must not be null";
131→            assert type != null : "type must not be null";
132→            fields.add(new FieldDefinition(name, type));
133→            return this;
134→        }
135→
136→        /**
137→         * Adds a vector field with the given element type and fixed dimensions.
138→         *
139→         * @param name the field name; must not be null
140→         * @param elementType the element precision; must be FLOAT16 or FLOAT32
141→         * @param dimensions the fixed number of elements per vector; must be positive
142→         * @return this builder
143→         */
144→        public Builder vectorField(String name, FieldType.Primitive elementType, int dimensions) {
145→            Objects.requireNonNull(name, "name must not be null");
146→            Objects.requireNonNull(elementType, "elementType must not be null");
147→            assert name != null : "name must not be null";
148→            assert elementType != null : "elementType must not be null";
149→            return field(name, FieldType.vector(elementType, dimensions));
150→        }
151→
152→        /**
153→         * Adds a nested object field by building its inner schema inline via a Consumer.
154→         *
155→         * <p>
156→         * The nested builder is passed to the consumer at {@code currentDepth + 1}. If the nested
157→         * depth exceeds maxDepth, {@link #build()} will throw.
158→         *
159→         * @param name the field name; must not be null
160→         * @param nested a consumer that populates the nested schema's builder; must not be null
161→         * @return this builder
162→         */
163→        public Builder objectField(String name, Consumer<Builder> nested) {
164→            Objects.requireNonNull(name, "name must not be null");
165→            Objects.requireNonNull(nested, "nested must not be null");
166→            assert name != null : "name must not be null";
167→            assert nested != null : "nested consumer must not be null";
168→
169→            final int nestedDepth = currentDepth + 1;
170→            final Builder root = (rootBuilder != null) ? rootBuilder : this;
171→            final Builder nestedBuilder = new Builder(name, version, nestedDepth, maxDepth, root);
172→            nested.accept(nestedBuilder);
173→
174→            // Build the nested ObjectType — validation happens here
175→            final List<FieldDefinition> nestedFields = nestedBuilder.buildFields(root.maxDepth);
176→            fields.add(new FieldDefinition(name, new FieldType.ObjectType(nestedFields)));
177→            return this;
178→        }
179→
180→        /**
181→         * Sets the maximum nesting depth allowed for object fields. Must be between 0 and 25
182→         * (inclusive).
183→         *
184→         * @param maxDepth the maximum depth
185→         * @return this builder
186→         * @throws IllegalArgumentException if {@code maxDepth} exceeds 25
187→         */
188→        public Builder maxDepth(int maxDepth) {
189→            if (maxDepth > ABSOLUTE_MAX_DEPTH) {
190→                throw new IllegalArgumentException("maxDepth " + maxDepth
191→                        + " exceeds absolute maximum of " + ABSOLUTE_MAX_DEPTH);
192→            }
193→            if (maxDepth < 0) {
194→                throw new IllegalArgumentException("maxDepth must not be negative");
195→            }
196→            this.maxDepth = maxDepth;
197→            return this;
198→        }
199→
200→        /**
201→         * Builds and returns the {@link JlsmSchema}.
202→         *
203→         * @return the constructed schema
204→         * @throws IllegalArgumentException if maxDepth exceeds 25 or if any field's nesting exceeds
205→         *             maxDepth
206→         */
207→        public JlsmSchema build() {
208→            if (maxDepth > ABSOLUTE_MAX_DEPTH) {
209→                throw new IllegalArgumentException("maxDepth " + maxDepth
210→                        + " exceeds absolute maximum of " + ABSOLUTE_MAX_DEPTH);
211→            }
212→            // Depth validation is already done eagerly in objectField → buildFields
213→            return new JlsmSchema(name, version, fields, maxDepth);
214→        }
215→
216→        /**
217→         * Internal helper: returns the fields accumulated by this builder, after validating that
218→         * {@code currentDepth <= allowedMaxDepth}.
219→         *
220→         * @param allowedMaxDepth the depth limit from the root builder
221→         * @return the list of field definitions
222→         * @throws IllegalArgumentException if this builder's depth exceeds allowedMaxDepth
223→         */
224→        private List<FieldDefinition> buildFields(int allowedMaxDepth) {
225→            if (currentDepth > allowedMaxDepth) {
226→                throw new IllegalArgumentException("Nested object depth " + currentDepth
227→                        + " exceeds maxDepth " + allowedMaxDepth);
228→            }
229→            return List.copyOf(fields);
230→        }
231→    }
232→}
