12→/**
13→ * Secondary index for vector nearest-neighbour search on a VectorType field. Wraps
14→ * {@code LsmVectorIndex} (IvfFlat or Hnsw) from jlsm-vector.
15→ *
16→ * <p>
17→ * Contract:
18→ * <ul>
19→ * <li>Supports: VectorNearest predicate only</li>
20→ * <li>The indexed field must be a VectorType with FLOAT32 or FLOAT16 element type</li>
21→ * <li>On insert: extracts the vector from the document and inserts into the vector index</li>
22→ * <li>On update: removes old vector, inserts new vector</li>
23→ * <li>On delete: removes the vector from the index</li>
24→ * <li>Caller chooses IvfFlat or Hnsw algorithm at table build time</li>
25→ * </ul>
26→ *
27→ * <p>
28→ * <b>Stub:</b> operations are not yet implemented. The constructor accepts the definition
29→ * so that IndexRegistry validation can complete, but all mutation and query operations
30→ * throw {@link UnsupportedOperationException}.
31→ */
32→public final class VectorFieldIndex implements SecondaryIndex {
33→
34→    private final IndexDefinition definition;
35→
36→    /**
37→     * Creates a new vector field index stub.
38→     *
39→     * @param definition the index definition (must be VECTOR type with similarity function)
40→     * @throws IOException if the backing index cannot be created
41→     */
42→    public VectorFieldIndex(IndexDefinition definition) throws IOException {
43→        Objects.requireNonNull(definition, "definition");
44→        assert definition.indexType() == jlsm.table.IndexType.VECTOR
45→                : "VectorFieldIndex requires VECTOR index type";
46→        this.definition = definition;
47→    }
48→
49→    @Override
50→    public IndexDefinition definition() {
51→        return definition;
52→    }
53→
54→    @Override
55→    public void onInsert(MemorySegment primaryKey, Object fieldValue) throws IOException {
56→        throw new UnsupportedOperationException("VectorFieldIndex.onInsert not implemented");
57→    }
58→
59→    @Override
60→    public void onUpdate(MemorySegment primaryKey, Object oldFieldValue, Object newFieldValue)
61→            throws IOException {
62→        throw new UnsupportedOperationException("VectorFieldIndex.onUpdate not implemented");
63→    }
64→
65→    @Override
66→    public void onDelete(MemorySegment primaryKey, Object fieldValue) throws IOException {
67→        throw new UnsupportedOperationException("VectorFieldIndex.onDelete not implemented");
68→    }
69→
70→    @Override
71→    public Iterator<MemorySegment> lookup(Predicate predicate) throws IOException {
72→        throw new UnsupportedOperationException("VectorFieldIndex.lookup not implemented");
73→    }
74→
75→    @Override
76→    public boolean supports(Predicate predicate) {
77→        return predicate instanceof Predicate.VectorNearest vn
78→                && vn.field().equals(definition.fieldName());
