  1→package jlsm.table.internal;
  2→
  3→import jlsm.table.FieldDefinition;
  4→import jlsm.table.FieldType;
  5→import jlsm.table.Float16;
  6→import jlsm.table.JlsmDocument;
  7→import jlsm.table.JlsmSchema;
  8→
  9→/**
 10→ * Serializes a {@link JlsmDocument} to a JSON string.
 11→ *
 12→ * <p>
 13→ * Thread-safe for concurrent use; each {@link #write} call creates its own {@link StringBuilder}.
 14→ */
 15→public final class JsonWriter {
 16→
 17→    /** Creates a new JsonWriter. */
 18→    public JsonWriter() {
 19→    }
 20→
 21→    /**
 22→     * Serializes the document to JSON.
 23→     *
 24→     * @param doc the document to serialize; must not be null
 25→     * @param indent spaces per indent level (0 = compact, &gt;0 = pretty)
 26→     * @return a JSON string
 27→     */
 28→    public String write(JlsmDocument doc, int indent) {
 29→        assert doc != null : "doc must not be null";
 30→        assert indent >= 0 : "indent must not be negative";
 31→
 32→        final StringBuilder sb = new StringBuilder(256);
 33→        writeDocument(doc, sb, indent, 0);
 34→        return sb.toString();
 35→    }
 36→
 37→    // -------------------------------------------------------------------------
 38→    // Private helpers
 39→    // -------------------------------------------------------------------------
 40→
 41→    private void writeDocument(JlsmDocument doc, StringBuilder sb, int indent, int depth) {
 42→        assert doc != null : "doc must not be null";
 43→        assert sb != null : "sb must not be null";
 44→
 45→        final JlsmSchema schema = doc.schema();
 46→        final Object[] values = DocumentAccess.get().values(doc);
 47→
 48→        sb.append('{');
 49→
 50→        boolean firstField = true;
 51→        for (int i = 0; i < schema.fields().size(); i++) {
 52→            final FieldDefinition fd = schema.fields().get(i);
 53→            final Object value = values[i];
 54→
 55→            if (!firstField) {
 56→                sb.append(',');
 57→            }
 58→            firstField = false;
 59→
 60→            if (indent > 0) {
 61→                sb.append('\n');
 62→                appendIndent(sb, indent, depth + 1);
 63→            }
 64→
 65→            writeString(fd.name(), sb);
 66→            sb.append(':');
 67→            if (indent > 0) {
 68→                sb.append(' ');
 69→            }
 70→
 71→            writeValue(fd.type(), value, sb, indent, depth + 1);
 72→        }
 73→
 74→        if (indent > 0 && !schema.fields().isEmpty()) {
 75→            sb.append('\n');
 76→            appendIndent(sb, indent, depth);
 77→        }
 78→        sb.append('}');
 79→    }
 80→
 81→    private void writeValue(FieldType type, Object value, StringBuilder sb, int indent, int depth) {
 82→        assert sb != null : "sb must not be null";
 83→
 84→        if (value == null) {
 85→            sb.append("null");
 86→            return;
 87→        }
 88→
 89→        switch (type) {
 90→            case FieldType.Primitive p -> writePrimitive(p, value, sb, indent, depth);
 91→            case FieldType.ArrayType at -> writeArray(at, (Object[]) value, sb, indent, depth);
 92→            case FieldType.VectorType vt -> writeVector(vt, value, sb, indent, depth);
 93→            case FieldType.ObjectType _ -> writeDocument((JlsmDocument) value, sb, indent, depth);
 94→        }
 95→    }
 96→
 97→    private void writePrimitive(FieldType.Primitive p, Object value, StringBuilder sb, int indent,
 98→            int depth) {
 99→        assert p != null : "p must not be null";
100→        assert value != null : "value must not be null";
101→        assert sb != null : "sb must not be null";
102→
103→        switch (p) {
104→            case STRING -> writeString((String) value, sb);
105→            case INT8 -> sb.append((Byte) value);
106→            case INT16 -> sb.append((Short) value);
107→            case INT32 -> sb.append((Integer) value);
108→            case INT64 -> sb.append((Long) value);
109→            case FLOAT16 -> {
110→                final float f = Float16.toFloat((Short) value);
111→                writeFloat(f, sb);
112→            }
113→            case FLOAT32 -> writeFloat((Float) value, sb);
114→            case FLOAT64 -> writeDouble((Double) value, sb);
115→            case BOOLEAN -> sb.append((Boolean) value ? "true" : "false");
116→            case TIMESTAMP -> sb.append((Long) value);
117→        }
118→    }
119→
120→    private void writeArray(FieldType.ArrayType at, Object[] elements, StringBuilder sb, int indent,
121→            int depth) {
122→        assert at != null : "at must not be null";
123→        assert elements != null : "elements must not be null";
124→        assert sb != null : "sb must not be null";
125→
126→        sb.append('[');
127→        for (int i = 0; i < elements.length; i++) {
128→            if (i > 0) {
129→                sb.append(',');
130→                if (indent > 0) {
131→                    sb.append(' ');
132→                }
133→            }
134→            writeValue(at.elementType(), elements[i], sb, indent, depth);
135→        }
136→        sb.append(']');
137→    }
138→
139→    private void writeVector(FieldType.VectorType vt, Object value, StringBuilder sb, int indent,
140→            int depth) {
141→        assert vt != null : "vt must not be null";
142→        assert value != null : "value must not be null";
143→        assert sb != null : "sb must not be null";
144→
145→        sb.append('[');
146→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
147→            final float[] vec = (float[]) value;
148→            for (int i = 0; i < vec.length; i++) {
149→                if (i > 0) {
150→                    sb.append(',');
151→                    if (indent > 0) {
152→                        sb.append(' ');
153→                    }
154→                }
155→                writeFloat(vec[i], sb);
156→            }
157→        } else {
158→            final short[] vec = (short[]) value;
159→            for (int i = 0; i < vec.length; i++) {
160→                if (i > 0) {
161→                    sb.append(',');
162→                    if (indent > 0) {
163→                        sb.append(' ');
164→                    }
165→                }
166→                writeFloat(Float16.toFloat(vec[i]), sb);
167→            }
168→        }
169→        sb.append(']');
170→    }
171→
172→    private static void writeFloat(float f, StringBuilder sb) {
173→        assert sb != null : "sb must not be null";
174→
175→        if (!Float.isFinite(f)) {
176→            sb.append("null");
177→        } else {
178→            sb.append(f);
179→        }
180→    }
181→
182→    private static void writeDouble(double d, StringBuilder sb) {
183→        assert sb != null : "sb must not be null";
184→
185→        if (!Double.isFinite(d)) {
186→            sb.append("null");
187→        } else {
188→            sb.append(d);
189→        }
190→    }
191→
192→    /**
193→     * Appends a JSON-escaped string (with surrounding quotes) to the builder.
194→     *
195→     * @param s the string to escape; must not be null
196→     * @param sb the builder to append to; must not be null
197→     */
198→    private static void writeString(String s, StringBuilder sb) {
199→        assert s != null : "s must not be null";
200→        assert sb != null : "sb must not be null";
201→
202→        sb.append('"');
203→        for (int i = 0; i < s.length(); i++) {
204→            final char c = s.charAt(i);
205→            switch (c) {
206→                case '"' -> sb.append("\\\"");
207→                case '\\' -> sb.append("\\\\");
208→                case '\n' -> sb.append("\\n");
209→                case '\r' -> sb.append("\\r");
210→                case '\t' -> sb.append("\\t");
211→                case '\b' -> sb.append("\\b");
212→                case '\f' -> sb.append("\\f");
213→                default -> sb.append(c);
214→            }
215→        }
216→        sb.append('"');
217→    }
218→
219→    private static void appendIndent(StringBuilder sb, int indent, int depth) {
220→        assert sb != null : "sb must not be null";
221→        assert indent >= 0 : "indent must not be negative";
222→        assert depth >= 0 : "depth must not be negative";
223→
224→        final int spaces = indent * depth;
225→        for (int i = 0; i < spaces; i++) {
226→            sb.append(' ');
227→        }
228→    }
229→}
