  1→package jlsm.table;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jdk.incubator.vector.ByteVector;
  5→import jdk.incubator.vector.DoubleVector;
  6→import jdk.incubator.vector.FloatVector;
  7→import jdk.incubator.vector.IntVector;
  8→import jdk.incubator.vector.LongVector;
  9→import jdk.incubator.vector.VectorShuffle;
 10→import jdk.incubator.vector.VectorSpecies;
 11→
 12→import java.lang.foreign.MemorySegment;
 13→import java.lang.foreign.ValueLayout;
 14→import java.nio.charset.StandardCharsets;
 15→import java.util.List;
 16→import java.util.Objects;
 17→
 18→/**
 19→ * Binary serializer for {@link JlsmDocument} values.
 20→ *
 21→ * <p>
 22→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 23→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 24→ *
 25→ * <p>
 26→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 27→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 28→ * {@code null}.
 29→ *
 30→ * <p>
 31→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 32→ * {@code jdk.incubator.vector}.
 33→ */
 34→public final class DocumentSerializer {
 35→
 36→    private DocumentSerializer() {
 37→    }
 38→
 39→    /**
 40→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 41→     * schema.
 42→     *
 43→     * @param schema the schema describing the document structure; must not be null
 44→     * @return a MemorySerializer for JlsmDocument
 45→     */
 46→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 47→        Objects.requireNonNull(schema, "schema must not be null");
 48→        return new SchemaSerializer(schema);
 49→    }
 50→
 51→    // =========================================================================
 52→    // Implementation
 53→    // =========================================================================
 54→
 55→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 56→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 57→
 58→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 59→    private static final VectorShuffle<Byte> BSWAP32;
 60→
 61→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 62→    private static final VectorShuffle<Byte> BSWAP64;
 63→
 64→    static {
 65→        final int byteLen = BYTE_SPECIES.length();
 66→        final int[] idx32 = new int[byteLen];
 67→        final int[] idx64 = new int[byteLen];
 68→        for (int i = 0; i + 3 < byteLen; i += 4) {
 69→            idx32[i + 0] = i + 3;
 70→            idx32[i + 1] = i + 2;
 71→            idx32[i + 2] = i + 1;
 72→            idx32[i + 3] = i + 0;
 73→        }
 74→        for (int i = 0; i + 7 < byteLen; i += 8) {
 75→            idx64[i + 0] = i + 7;
 76→            idx64[i + 1] = i + 6;
 77→            idx64[i + 2] = i + 5;
 78→            idx64[i + 3] = i + 4;
 79→            idx64[i + 4] = i + 3;
 80→            idx64[i + 5] = i + 2;
 81→            idx64[i + 6] = i + 1;
 82→            idx64[i + 7] = i + 0;
 83→        }
 84→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
 85→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
 86→    }
 87→
 88→    // -------------------------------------------------------------------------
 89→    // Serializer implementation
 90→    // -------------------------------------------------------------------------
 91→
 92→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
 93→
 94→        private final JlsmSchema schema;
 95→
 96→        SchemaSerializer(JlsmSchema schema) {
 97→            this.schema = schema;
 98→        }
 99→
100→        @Override
101→        public MemorySegment serialize(JlsmDocument doc) {
102→            Objects.requireNonNull(doc, "doc must not be null");
103→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
104→                    : "document schema mismatch";
105→
106→            final List<FieldDefinition> fields = schema.fields();
107→            final int fieldCount = fields.size();
108→            final Object[] values = doc.values();
109→
110→            // Count boolean fields
111→            final int boolCount = countBoolFields(fields);
112→
113→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
114→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
115→            final int nullMaskBytes = (fieldCount + 7) / 8;
116→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
117→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
118→
119→            // Two-pass: measure then encode
120→            final int payloadSize = measureFields(fields, values);
121→            final int totalSize = headerSize + payloadSize;
122→
123→            final byte[] buf = new byte[totalSize];
124→
125→            // Write header
126→            writeShortBE(buf, 0, (short) schema.version());
127→            writeShortBE(buf, 2, (short) fieldCount);
128→            // Null bitmask
129→            buildNullMask(fields, values, buf, 4);
130→            // Boolean bitmask
131→            if (boolCount > 0) {
132→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
133→            }
134→
135→            // Write values
136→            final Cursor cursor = new Cursor(buf, headerSize);
137→            encodeFields(fields, values, cursor);
138→
139→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
140→            return MemorySegment.ofArray(buf);
141→        }
142→
143→        @Override
144→        public JlsmDocument deserialize(MemorySegment segment) {
145→            Objects.requireNonNull(segment, "segment must not be null");
146→
147→            final byte[] buf = segment.toArray(ValueLayout.JAVA_BYTE);
148→            final Cursor cursor = new Cursor(buf, 0);
149→
150→            // Read header
151→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
152→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
153→
154→            final List<FieldDefinition> currentFields = schema.fields();
155→            final int currentFieldCount = currentFields.size();
156→
157→            // We only read min(writeFieldCount, currentFieldCount) fields
158→            final int readCount = Math.min(writeFieldCount, currentFieldCount);
159→
160→            // Count bool fields in the *write-time* schema (same field list up to writeFieldCount)
161→            // We use the current schema's first writeFieldCount fields for the null/bool masks.
162→            // For the boolMask we count booleans among the first writeFieldCount fields.
163→            final int writeBoolCount = countBoolFieldsUpTo(currentFields, writeFieldCount);
164→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
165→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
166→
167→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
168→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
169→
170→            // Decode values
171→            final Object[] values = new Object[currentFieldCount];
172→            // Fields beyond readCount remain null (new fields added in a later schema version)
173→
174→            int boolIdx = 0; // index among BOOLEAN fields seen so far
175→            for (int i = 0; i < readCount; i++) {
176→                final FieldDefinition fd = currentFields.get(i);
177→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
178→                if (isNull) {
179→                    // Track bool index even when null
180→                    if (fd.type() == FieldType.Primitive.BOOLEAN) {
181→                        boolIdx++;
182→                    }
183→                    values[i] = null;
184→                    continue;
185→                }
186→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
187→                    // Value is encoded in the bool bitmask
188→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
189→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
190→                    boolIdx++;
191→                } else {
192→                    values[i] = decodeField(buf, cursor, fd.type());
193→                }
194→            }
195→
196→            // If writeFieldCount > currentFieldCount we need to skip the extra encoded fields.
197→            // However, since we can't know the sizes of unknown fields (their types may differ
198→            // from the current schema), we handle schema shrinkage gracefully by only reading
199→            // min(writeFieldCount, currentFieldCount). Extra write-time fields beyond the current
200→            // schema are simply ignored — the cursor position won't matter after this point.
201→
202→            return new JlsmDocument(schema, values);
203→        }
204→    }
205→
206→    // =========================================================================
207→    // Measure helpers (first pass)
208→    // =========================================================================
209→
210→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
211→        int total = 0;
212→        for (int i = 0; i < fields.size(); i++) {
213→            final FieldDefinition fd = fields.get(i);
214→            final Object val = values[i];
215→            if (val == null) {
216→                continue; // null → no value bytes
217→            }
218→            total += measureField(fd.type(), val);
219→        }
220→        return total;
221→    }
222→
223→    private static int measureField(FieldType type, Object value) {
224→        return switch (type) {
225→            case FieldType.Primitive p -> switch (p) {
226→                case STRING -> {
227→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
228→                    yield varIntSize(utf8.length) + utf8.length;
229→                }
230→                case INT8 -> 1;
231→                case INT16 -> 2;
232→                case INT32 -> 4;
233→                case INT64 -> 8;
234→                case FLOAT16 -> 2;
235→                case FLOAT32 -> 4;
236→                case FLOAT64 -> 8;
237→                case BOOLEAN -> 0; // packed in bitmask
238→                case TIMESTAMP -> 8;
239→            };
240→            case FieldType.ArrayType at -> {
241→                final Object[] arr = (Object[]) value;
242→                int sz = varIntSize(arr.length);
243→                for (Object elem : arr) {
244→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
245→                }
246→                yield sz;
247→            }
248→            case FieldType.VectorType vt -> {
249→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
250→                yield vt.dimensions() * elemBytes;
251→            }
252→            case FieldType.ObjectType ot -> {
253→                final JlsmDocument sub = (JlsmDocument) value;
254→                final List<FieldDefinition> subFields = ot.fields();
255→                final int subBoolCount = countBoolFields(subFields);
256→                final int subNullBytes = (subFields.size() + 7) / 8;
257→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
258→                int sz = subNullBytes + subBoolBytes;
259→                sz += measureFields(subFields, sub.values());
260→                yield sz;
261→            }
262→        };
263→    }
264→
265→    // =========================================================================
266→    // Encode helpers (second pass)
267→    // =========================================================================
268→
269→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
270→        for (int i = 0; i < fields.size(); i++) {
271→            final Object val = values[i];
272→            if (val == null) {
273→                continue;
274→            }
275→            encodeField(c, fields.get(i).type(), val);
276→        }
277→    }
278→
279→    private static void encodeField(Cursor c, FieldType type, Object value) {
280→        switch (type) {
281→            case FieldType.Primitive p -> {
282→                switch (p) {
283→                    case STRING -> {
284→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
285→                        writeVarInt(c, utf8.length);
286→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
287→                        c.pos += utf8.length;
288→                    }
289→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
290→                    case INT16 -> {
291→                        writeShortBE(c.buf, c.pos, (Short) value);
292→                        c.pos += 2;
293→                    }
294→                    case INT32 -> {
295→                        writeIntBE(c.buf, c.pos, (Integer) value);
296→                        c.pos += 4;
297→                    }
298→                    case INT64 -> {
299→                        writeLongBE(c.buf, c.pos, (Long) value);
300→                        c.pos += 8;
301→                    }
302→                    case FLOAT16 -> {
303→                        writeShortBE(c.buf, c.pos, (Short) value);
304→                        c.pos += 2;
305→                    }
306→                    case FLOAT32 -> {
307→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
308→                        c.pos += 4;
309→                    }
310→                    case FLOAT64 -> {
311→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
312→                        c.pos += 8;
313→                    }
314→                    case BOOLEAN -> {
315→                        // Boolean values are packed in the bool bitmask; nothing here
316→                    }
317→                    case TIMESTAMP -> {
318→                        writeLongBE(c.buf, c.pos, (Long) value);
319→                        c.pos += 8;
320→                    }
321→                }
322→            }
323→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
324→            case FieldType.VectorType vt -> encodeVector(c, vt, value);
325→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
326→        }
327→    }
328→
329→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
330→        writeVarInt(c, arr.length);
331→        // SIMD-accelerated paths for contiguous numeric types
332→        if (elemType == FieldType.Primitive.INT32) {
333→            encodeInt32Array(c, arr);
334→        } else if (elemType == FieldType.Primitive.INT64) {
335→            encodeInt64Array(c, arr);
336→        } else if (elemType == FieldType.Primitive.FLOAT32) {
337→            encodeFloat32Array(c, arr);
338→        } else if (elemType == FieldType.Primitive.FLOAT64) {
339→            encodeFloat64Array(c, arr);
340→        } else {
341→            for (Object elem : arr) {
342→                if (elem != null) {
343→                    encodeField(c, elemType, elem);
344→                }
345→            }
346→        }
347→    }
348→
349→    private static void encodeVector(Cursor c, FieldType.VectorType vt, Object value) {
350→        final int d = vt.dimensions();
351→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
352→            final float[] vec = (float[]) value;
353→            assert vec.length == d : "vector length must match dimensions";
354→            for (int i = 0; i < d; i++) {
355→                writeIntBE(c.buf, c.pos, Float.floatToRawIntBits(vec[i]));
356→                c.pos += 4;
357→            }
358→        } else {
359→            // FLOAT16 — stored as short[]
360→            final short[] vec = (short[]) value;
361→            assert vec.length == d : "vector length must match dimensions";
362→            for (int i = 0; i < d; i++) {
363→                writeShortBE(c.buf, c.pos, vec[i]);
364→                c.pos += 2;
365→            }
366→        }
367→    }
368→
369→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
370→        final List<FieldDefinition> subFields = ot.fields();
371→        final Object[] subValues = sub.values();
372→        final int boolCount = countBoolFields(subFields);
373→        final int nullMaskBytes = (subFields.size() + 7) / 8;
374→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
375→
376→        final int nullMaskStart = c.pos;
377→        c.pos += nullMaskBytes;
378→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
379→        if (boolCount > 0) {
380→            c.pos += boolMaskBytes;
381→        }
382→
383→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
384→        if (boolCount > 0) {
385→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
386→        }
387→        encodeFields(subFields, subValues, c);
388→    }
389→
390→    // =========================================================================
391→    // SIMD encode paths
392→    // =========================================================================
393→
394→    private static void encodeInt32Array(Cursor c, Object[] arr) {
395→        final int simdLen = BYTE_SPECIES.length(); // bytes per SIMD register
396→        // Only use SIMD if we have enough data (at least one full vector worth of 4-byte ints)
397→        final int simdElems = simdLen / 4; // number of int32 elements per SIMD operation
398→        int i = 0;
399→        if (arr.length >= simdElems && simdLen >= 4) {
400→            final int[] ints = new int[simdElems];
401→            while (i + simdElems <= arr.length) {
402→                for (int j = 0; j < simdElems; j++) {
403→                    ints[j] = (Integer) arr[i + j];
404→                }
405→                // Load as bytes (little-endian native), swap to big-endian
406→                final ByteVector bv = IntVector.fromArray(IntVector.SPECIES_PREFERRED, ints, 0)
407→                        .reinterpretAsBytes();
408→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
409→                c.pos += simdLen;
410→                i += simdElems;
411→            }
412→        }
413→        // Scalar remainder
414→        while (i < arr.length) {
415→            writeIntBE(c.buf, c.pos, (Integer) arr[i++]);
416→            c.pos += 4;
417→        }
418→    }
419→
420→    private static void encodeInt64Array(Cursor c, Object[] arr) {
421→        final int simdLen = BYTE_SPECIES.length();
422→        final int simdElems = simdLen / 8;
423→        int i = 0;
424→        if (arr.length >= simdElems && simdLen >= 8) {
425→            final long[] longs = new long[simdElems];
426→            while (i + simdElems <= arr.length) {
427→                for (int j = 0; j < simdElems; j++) {
428→                    longs[j] = (Long) arr[i + j];
429→                }
430→                final ByteVector bv = LongVector.fromArray(LongVector.SPECIES_PREFERRED, longs, 0)
431→                        .reinterpretAsBytes();
432→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
433→                c.pos += simdLen;
434→                i += simdElems;
435→            }
436→        }
437→        while (i < arr.length) {
438→            writeLongBE(c.buf, c.pos, (Long) arr[i++]);
439→            c.pos += 8;
440→        }
441→    }
442→
443→    private static void encodeFloat32Array(Cursor c, Object[] arr) {
444→        final int simdLen = BYTE_SPECIES.length();
445→        final int simdElems = simdLen / 4;
446→        int i = 0;
447→        if (arr.length >= simdElems && simdLen >= 4) {
448→            final float[] floats = new float[simdElems];
449→            while (i + simdElems <= arr.length) {
450→                for (int j = 0; j < simdElems; j++) {
451→                    floats[j] = (Float) arr[i + j];
452→                }
453→                final ByteVector bv = FloatVector
454→                        .fromArray(FloatVector.SPECIES_PREFERRED, floats, 0).reinterpretAsBytes();
455→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
456→                c.pos += simdLen;
457→                i += simdElems;
458→            }
459→        }
460→        while (i < arr.length) {
461→            writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) arr[i++]));
462→            c.pos += 4;
463→        }
464→    }
465→
466→    private static void encodeFloat64Array(Cursor c, Object[] arr) {
467→        final int simdLen = BYTE_SPECIES.length();
468→        final int simdElems = simdLen / 8;
469→        int i = 0;
470→        if (arr.length >= simdElems && simdLen >= 8) {
471→            final double[] doubles = new double[simdElems];
472→            while (i + simdElems <= arr.length) {
473→                for (int j = 0; j < simdElems; j++) {
474→                    doubles[j] = (Double) arr[i + j];
475→                }
476→                final ByteVector bv = DoubleVector
477→                        .fromArray(DoubleVector.SPECIES_PREFERRED, doubles, 0).reinterpretAsBytes();
478→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
479→                c.pos += simdLen;
480→                i += simdElems;
481→            }
482→        }
483→        while (i < arr.length) {
484→            writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) arr[i++]));
485→            c.pos += 8;
486→        }
487→    }
488→
489→    // =========================================================================
490→    // Decode helpers
491→    // =========================================================================
492→
493→    private static Object decodeField(byte[] buf, Cursor cursor, FieldType type) {
494→        return switch (type) {
495→            case FieldType.Primitive p -> switch (p) {
496→                case STRING -> {
497→                    final int len = readVarInt(buf, cursor);
498→                    final String s = new String(buf, cursor.pos, len, StandardCharsets.UTF_8);
499→                    cursor.pos += len;
500→                    yield s;
501→                }
502→                case INT8 -> buf[cursor.pos++];
503→                case INT16 -> {
504→                    final short v = readShortBE(buf, cursor.pos);
505→                    cursor.pos += 2;
506→                    yield v;
507→                }
508→                case INT32 -> {
509→                    final int v = readIntBE(buf, cursor.pos);
510→                    cursor.pos += 4;
511→                    yield v;
512→                }
513→                case INT64 -> {
514→                    final long v = readLongBE(buf, cursor.pos);
515→                    cursor.pos += 8;
516→                    yield v;
517→                }
518→                case FLOAT16 -> {
519→                    final short v = readShortBE(buf, cursor.pos);
520→                    cursor.pos += 2;
521→                    yield v;
522→                }
523→                case FLOAT32 -> {
524→                    final float v = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
525→                    cursor.pos += 4;
526→                    yield v;
527→                }
528→                case FLOAT64 -> {
529→                    final double v = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
530→                    cursor.pos += 8;
531→                    yield v;
532→                }
533→                case BOOLEAN ->
534→                    throw new AssertionError("BOOLEAN should be handled via bool bitmask");
535→                case TIMESTAMP -> {
536→                    final long v = readLongBE(buf, cursor.pos);
537→                    cursor.pos += 8;
538→                    yield v;
539→                }
540→            };
541→            case FieldType.ArrayType at -> decodeArray(buf, cursor, at);
542→            case FieldType.VectorType vt -> decodeVector(buf, cursor, vt);
543→            case FieldType.ObjectType ot -> decodeObject(buf, cursor, ot);
544→        };
545→    }
546→
547→    private static Object[] decodeArray(byte[] buf, Cursor cursor, FieldType.ArrayType at) {
548→        final int count = readVarInt(buf, cursor);
549→        // SIMD-accelerated decode for contiguous numeric types
550→        final FieldType elemType = at.elementType();
551→        if (elemType == FieldType.Primitive.INT32) {
552→            return decodeInt32Array(buf, cursor, count);
553→        } else if (elemType == FieldType.Primitive.INT64) {
554→            return decodeInt64Array(buf, cursor, count);
555→        } else if (elemType == FieldType.Primitive.FLOAT32) {
556→            return decodeFloat32Array(buf, cursor, count);
557→        } else if (elemType == FieldType.Primitive.FLOAT64) {
558→            return decodeFloat64Array(buf, cursor, count);
559→        }
560→        final Object[] arr = new Object[count];
561→        for (int i = 0; i < count; i++) {
562→            arr[i] = decodeField(buf, cursor, elemType);
563→        }
564→        return arr;
565→    }
566→
567→    private static Object decodeVector(byte[] buf, Cursor cursor, FieldType.VectorType vt) {
568→        final int d = vt.dimensions();
569→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
570→            final float[] vec = new float[d];
571→            for (int i = 0; i < d; i++) {
572→                vec[i] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
573→                cursor.pos += 4;
574→            }
575→            return vec;
576→        } else {
577→            // FLOAT16 — return as short[]
578→            final short[] vec = new short[d];
579→            for (int i = 0; i < d; i++) {
580→                vec[i] = readShortBE(buf, cursor.pos);
581→                cursor.pos += 2;
582→            }
583→            return vec;
584→        }
585→    }
586→
587→    private static Object decodeObject(byte[] buf, Cursor cursor, FieldType.ObjectType ot) {
588→        final List<FieldDefinition> subFields = ot.fields();
589→        final int subFieldCount = subFields.size();
590→        final int subBoolCount = countBoolFields(subFields);
591→        final int nullMaskBytes = (subFieldCount + 7) / 8;
592→        final int boolMaskBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
593→
594→        final int nullMaskOffset = cursor.advance(nullMaskBytes);
595→        final int boolMaskOffset = subBoolCount > 0 ? cursor.advance(boolMaskBytes) : -1;
596→
597→        final Object[] subValues = new Object[subFieldCount];
598→        int boolIdx = 0;
599→        for (int i = 0; i < subFieldCount; i++) {
600→            final FieldDefinition fd = subFields.get(i);
601→            final boolean isNull = isNullBit(buf, nullMaskOffset, i);
602→            if (isNull) {
603→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
604→                    boolIdx++;
605→                }
606→                subValues[i] = null;
607→                continue;
608→            }
609→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
610→                assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
611→                subValues[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
612→                boolIdx++;
613→            } else {
614→                subValues[i] = decodeField(buf, cursor, fd.type());
615→            }
616→        }
617→
618→        // Synthesize a schema for the sub-document
619→        final JlsmSchema subSchema = ot.toSchema("nested", 0);
620→        return new JlsmDocument(subSchema, subValues);
621→    }
