623→    // =========================================================================
624→    // SIMD decode paths
625→    // =========================================================================
626→
627→    private static Object[] decodeInt32Array(byte[] buf, Cursor cursor, int count) {
628→        final Object[] result = new Object[count];
629→        final int simdLen = BYTE_SPECIES.length();
630→        final int simdElems = simdLen / 4;
631→        final int[] tmp = new int[simdElems];
632→        int i = 0;
633→        if (count >= simdElems && simdLen >= 4) {
634→            while (i + simdElems <= count) {
635→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
636→                        .reinterpretAsInts().intoArray(tmp, 0);
637→                for (int j = 0; j < simdElems; j++) {
638→                    result[i + j] = tmp[j];
639→                }
640→                cursor.pos += simdLen;
641→                i += simdElems;
642→            }
643→        }
644→        while (i < count) {
645→            result[i++] = readIntBE(buf, cursor.pos);
646→            cursor.pos += 4;
647→        }
648→        return result;
649→    }
650→
651→    private static Object[] decodeInt64Array(byte[] buf, Cursor cursor, int count) {
652→        final Object[] result = new Object[count];
653→        final int simdLen = BYTE_SPECIES.length();
654→        final int simdElems = simdLen / 8;
655→        final long[] tmp = new long[simdElems];
656→        int i = 0;
657→        if (count >= simdElems && simdLen >= 8) {
658→            while (i + simdElems <= count) {
659→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
660→                        .reinterpretAsLongs().intoArray(tmp, 0);
661→                for (int j = 0; j < simdElems; j++) {
662→                    result[i + j] = tmp[j];
663→                }
664→                cursor.pos += simdLen;
665→                i += simdElems;
666→            }
667→        }
668→        while (i < count) {
669→            result[i++] = readLongBE(buf, cursor.pos);
670→            cursor.pos += 8;
671→        }
672→        return result;
673→    }
674→
675→    private static Object[] decodeFloat32Array(byte[] buf, Cursor cursor, int count) {
676→        final Object[] result = new Object[count];
677→        final int simdLen = BYTE_SPECIES.length();
678→        final int simdElems = simdLen / 4;
679→        final float[] tmp = new float[simdElems];
680→        int i = 0;
681→        if (count >= simdElems && simdLen >= 4) {
682→            while (i + simdElems <= count) {
683→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
684→                        .reinterpretAsFloats().intoArray(tmp, 0);
685→                for (int j = 0; j < simdElems; j++) {
686→                    result[i + j] = tmp[j];
687→                }
688→                cursor.pos += simdLen;
689→                i += simdElems;
690→            }
691→        }
692→        while (i < count) {
693→            result[i++] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
694→            cursor.pos += 4;
695→        }
696→        return result;
697→    }
698→
699→    private static Object[] decodeFloat64Array(byte[] buf, Cursor cursor, int count) {
700→        final Object[] result = new Object[count];
701→        final int simdLen = BYTE_SPECIES.length();
702→        final int simdElems = simdLen / 8;
703→        final double[] tmp = new double[simdElems];
704→        int i = 0;
705→        if (count >= simdElems && simdLen >= 8) {
706→            while (i + simdElems <= count) {
707→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
708→                        .reinterpretAsDoubles().intoArray(tmp, 0);
709→                for (int j = 0; j < simdElems; j++) {
710→                    result[i + j] = tmp[j];
711→                }
712→                cursor.pos += simdLen;
713→                i += simdElems;
714→            }
715→        }
716→        while (i < count) {
717→            result[i++] = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
718→            cursor.pos += 8;
719→        }
720→        return result;
721→    }
