723→    // =========================================================================
724→    // Bitmask helpers
725→    // =========================================================================
726→
727→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
728→            int offset) {
729→        for (int i = 0; i < fields.size(); i++) {
730→            if (values[i] == null) {
731→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
732→            }
733→        }
734→    }
735→
736→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
737→            int offset) {
738→        int boolIdx = 0;
739→        for (int i = 0; i < fields.size(); i++) {
740→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
741→                final Object val = values[i];
742→                if (val instanceof Boolean b && b) {
743→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
744→                }
745→                boolIdx++;
746→            }
747→        }
748→    }
749→
750→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
751→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
752→    }
753→
754→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
755→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
756→    }
757→
758→    private static int countBoolFields(List<FieldDefinition> fields) {
759→        int count = 0;
760→        for (final FieldDefinition fd : fields) {
761→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
762→                count++;
763→            }
764→        }
765→        return count;
766→    }
767→
768→    private static int countBoolFieldsUpTo(List<FieldDefinition> fields, int limit) {
769→        int count = 0;
770→        final int bound = Math.min(limit, fields.size());
771→        for (int i = 0; i < bound; i++) {
772→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
773→                count++;
774→            }
775→        }
776→        return count;
777→    }
778→
779→    // =========================================================================
780→    // VarInt (LEB128 unsigned)
781→    // =========================================================================
782→
783→    private static int varIntSize(int value) {
784→        assert value >= 0 : "VarInt value must be non-negative";
785→        if (value < 128) {
786→            return 1;
787→        }
788→        if (value < 16384) {
789→            return 2;
790→        }
791→        if (value < 2097152) {
792→            return 3;
793→        }
794→        if (value < 268435456) {
795→            return 4;
796→        }
797→        return 5;
798→    }
799→
800→    private static void writeVarInt(Cursor c, int value) {
801→        assert value >= 0 : "VarInt value must be non-negative";
802→        while (true) {
803→            if ((value & ~0x7F) == 0) {
804→                c.buf[c.pos++] = (byte) value;
805→                return;
806→            }
807→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
808→            value >>>= 7;
809→        }
810→    }
811→
812→    private static int readVarInt(byte[] buf, Cursor cursor) {
813→        int result = 0;
814→        int shift = 0;
815→        while (true) {
816→            final byte b = buf[cursor.pos++];
817→            result |= (b & 0x7F) << shift;
818→            if ((b & 0x80) == 0) {
819→                break;
820→            }
821→            shift += 7;
822→            assert shift <= 35 : "VarInt overflow — corrupt data";
823→        }
824→        return result;
825→    }
826→
827→    // =========================================================================
828→    // Primitive I/O
829→    // =========================================================================
830→
831→    private static void writeShortBE(byte[] buf, int offset, short value) {
832→        buf[offset] = (byte) (value >> 8);
833→        buf[offset + 1] = (byte) value;
834→    }
835→
836→    private static short readShortBE(byte[] buf, int offset) {
837→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
838→    }
839→
840→    private static void writeIntBE(byte[] buf, int offset, int value) {
841→        buf[offset] = (byte) (value >> 24);
842→        buf[offset + 1] = (byte) (value >> 16);
843→        buf[offset + 2] = (byte) (value >> 8);
844→        buf[offset + 3] = (byte) value;
845→    }
846→
847→    private static int readIntBE(byte[] buf, int offset) {
848→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
849→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
850→    }
851→
852→    private static void writeLongBE(byte[] buf, int offset, long value) {
853→        buf[offset] = (byte) (value >> 56);
854→        buf[offset + 1] = (byte) (value >> 48);
855→        buf[offset + 2] = (byte) (value >> 40);
856→        buf[offset + 3] = (byte) (value >> 32);
857→        buf[offset + 4] = (byte) (value >> 24);
858→        buf[offset + 5] = (byte) (value >> 16);
859→        buf[offset + 6] = (byte) (value >> 8);
860→        buf[offset + 7] = (byte) value;
861→    }
862→
863→    private static long readLongBE(byte[] buf, int offset) {
864→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
865→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
866→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
867→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
868→    }
869→
870→    // =========================================================================
871→    // Cursor
872→    // =========================================================================
873→
874→    /** Mutable position cursor for sequential byte-array I/O. */
875→    private static final class Cursor {
876→
877→        final byte[] buf;
878→        int pos;
879→
880→        Cursor(byte[] buf, int pos) {
881→            this.buf = buf;
882→            this.pos = pos;
883→        }
884→
885→        /** Advances position by {@code n} bytes and returns the old position. */
886→        int advance(int n) {
887→            final int old = pos;
888→            pos += n;
889→            return old;
890→        }
891→    }
892→}
