  1→package jlsm.table.internal;
  2→
  3→import java.nio.charset.StandardCharsets;
  4→import java.util.ArrayList;
  5→
  6→import jdk.incubator.vector.ByteVector;
  7→import jdk.incubator.vector.VectorSpecies;
  8→
  9→import jlsm.table.FieldDefinition;
 10→import jlsm.table.FieldType;
 11→import jlsm.table.Float16;
 12→import jlsm.table.JlsmDocument;
 13→import jlsm.table.JlsmSchema;
 14→
 15→/**
 16→ * State-machine JSON parser for {@link JlsmDocument}.
 17→ *
 18→ * <p>
 19→ * Parses JSON objects into {@link JlsmDocument} instances according to a provided
 20→ * {@link JlsmSchema}. Unknown fields are skipped; missing fields default to null. Type mismatches
 21→ * throw {@link IllegalArgumentException}. Malformed JSON throws {@link IllegalArgumentException}.
 22→ *
 23→ * <p>
 24→ * String scanning uses SIMD acceleration via {@code jdk.incubator.vector.ByteVector} to locate
 25→ * quote and backslash delimiters in bulk.
 26→ */
 27→public final class JsonParser {
 28→
 29→    private static final VectorSpecies<Byte> BSPECIES = ByteVector.SPECIES_PREFERRED;
 30→
 31→    /** Creates a new JsonParser. */
 32→    public JsonParser() {
 33→    }
 34→
 35→    /**
 36→     * Parses a JSON string into a {@link JlsmDocument}.
 37→     *
 38→     * @param json the JSON string; must not be null
 39→     * @param schema the target schema; must not be null
 40→     * @return a new JlsmDocument
 41→     * @throws IllegalArgumentException if the JSON is malformed or a field type does not match the
 42→     *             schema
 43→     */
 44→    public JlsmDocument parse(String json, JlsmSchema schema) {
 45→        if (json == null) {
 46→            throw new IllegalArgumentException("json must not be null");
 47→        }
 48→        if (schema == null) {
 49→            throw new IllegalArgumentException("schema must not be null");
 50→        }
 51→
 52→        final byte[] src = json.getBytes(StandardCharsets.UTF_8);
 53→        final int[] posRef = { 0 };
 54→
 55→        skipWhitespace(src, posRef);
 56→        final JlsmDocument result = parseObject(src, posRef, schema);
 57→        skipWhitespace(src, posRef);
 58→        if (posRef[0] != src.length) {
 59→            throw new IllegalArgumentException(
 60→                    "Unexpected content after JSON object at position " + posRef[0]);
 61→        }
 62→        return result;
 63→    }
 64→
 65→    // -------------------------------------------------------------------------
 66→    // Object parsing
 67→    // -------------------------------------------------------------------------
 68→
 69→    private JlsmDocument parseObject(byte[] src, int[] pos, JlsmSchema schema) {
 70→        assert src != null : "src must not be null";
 71→        assert pos != null : "pos must not be null";
 72→        assert schema != null : "schema must not be null";
 73→
 74→        expect(src, pos, '{');
 75→
 76→        final Object[] values = new Object[schema.fields().size()];
 77→
 78→        skipWhitespace(src, pos);
 79→        if (pos[0] < src.length && src[pos[0]] == '}') {
 80→            pos[0]++;
 81→            return DocumentAccess.get().create(schema, values);
 82→        }
 83→
 84→        boolean first = true;
 85→        while (pos[0] < src.length) {
 86→            if (!first) {
 87→                skipWhitespace(src, pos);
 88→                expect(src, pos, ',');
 89→            }
 90→            first = false;
 91→
 92→            skipWhitespace(src, pos);
 93→
 94→            // Check for end of object (trailing comma tolerance)
 95→            if (pos[0] < src.length && src[pos[0]] == '}') {
 96→                break;
 97→            }
 98→
 99→            // Parse field key
100→            final String key = parseString(src, pos);
101→
102→            skipWhitespace(src, pos);
103→            expect(src, pos, ':');
104→            skipWhitespace(src, pos);
105→
106→            final int fieldIdx = schema.fieldIndex(key);
107→            if (fieldIdx < 0) {
108→                // Unknown field — skip its value
109→                skipValue(src, pos);
110→            } else {
111→                final FieldDefinition fd = schema.fields().get(fieldIdx);
112→                values[fieldIdx] = parseValue(src, pos, fd.type(), fd.name(), schema);
113→            }
114→
115→            skipWhitespace(src, pos);
116→            if (pos[0] < src.length && src[pos[0]] == '}') {
117→                break;
118→            }
119→        }
120→
121→        skipWhitespace(src, pos);
122→        expect(src, pos, '}');
123→
124→        return DocumentAccess.get().create(schema, values);
125→    }
126→
127→    // -------------------------------------------------------------------------
128→    // Value parsing (dispatch by FieldType)
129→    // -------------------------------------------------------------------------
130→
131→    private Object parseValue(byte[] src, int[] pos, FieldType type, String fieldName,
132→            JlsmSchema parentSchema) {
133→        assert src != null : "src must not be null";
134→        assert pos != null : "pos must not be null";
135→        assert type != null : "type must not be null";
136→
137→        skipWhitespace(src, pos);
138→
139→        if (pos[0] >= src.length) {
140→            throw new IllegalArgumentException("Unexpected end of JSON");
141→        }
142→
143→        final byte b = src[pos[0]];
144→
145→        // null literal
146→        if (b == 'n') {
147→            parseLiteral(src, pos, "null");
148→            return null;
149→        }
150→
151→        return switch (type) {
152→            case FieldType.Primitive p -> parsePrimitive(src, pos, p, fieldName, b);
153→            case FieldType.ArrayType at -> parseArray(src, pos, at, fieldName, parentSchema);
154→            case FieldType.VectorType vt -> parseVector(src, pos, vt, fieldName);
155→            case FieldType.ObjectType ot -> {
156→                final JlsmSchema subSchema = ot.toSchema(fieldName, parentSchema.version());
157→                yield parseObject(src, pos, subSchema);
158→            }
159→        };
160→    }
161→
162→    private Object parsePrimitive(byte[] src, int[] pos, FieldType.Primitive p, String fieldName,
163→            byte firstByte) {
164→        assert src != null : "src must not be null";
165→        assert pos != null : "pos must not be null";
166→        assert p != null : "p must not be null";
167→
168→        return switch (p) {
169→            case STRING -> {
170→                if (firstByte != '"') {
171→                    throw new IllegalArgumentException("Field '" + fieldName
172→                            + "' expects STRING (quoted), got token starting with '"
173→                            + (char) firstByte + "'");
174→                }
175→                yield parseString(src, pos);
176→            }
177→            case BOOLEAN -> {
178→                if (firstByte != 't' && firstByte != 'f') {
179→                    throw new IllegalArgumentException("Field '" + fieldName
180→                            + "' expects BOOLEAN (true/false), got token starting with '"
181→                            + (char) firstByte + "'");
182→                }
183→                yield parseBoolean(src, pos);
184→            }
185→            case INT8 -> {
186→                requireNumeric(fieldName, firstByte);
187→                yield Byte.parseByte(parseNumberString(src, pos));
188→            }
189→            case INT16 -> {
190→                requireNumeric(fieldName, firstByte);
191→                yield Short.parseShort(parseNumberString(src, pos));
192→            }
193→            case INT32 -> {
194→                requireNumeric(fieldName, firstByte);
195→                final String numStr = parseNumberString(src, pos);
196→                try {
197→                    yield Integer.parseInt(numStr);
198→                } catch (NumberFormatException e) {
199→                    throw new IllegalArgumentException(
200→                            "Field '" + fieldName + "' INT32 value out of range: " + numStr, e);
201→                }
202→            }
203→            case INT64 -> {
204→                requireNumeric(fieldName, firstByte);
205→                yield Long.parseLong(parseNumberString(src, pos));
206→            }
207→            case FLOAT16 -> {
208→                requireNumeric(fieldName, firstByte);
209→                final float f = Float.parseFloat(parseNumberString(src, pos));
210→                yield Float16.fromFloat(f);
211→            }
212→            case FLOAT32 -> {
213→                requireNumeric(fieldName, firstByte);
214→                yield Float.parseFloat(parseNumberString(src, pos));
215→            }
216→            case FLOAT64 -> {
217→                requireNumeric(fieldName, firstByte);
218→                yield Double.parseDouble(parseNumberString(src, pos));
219→            }
220→            case TIMESTAMP -> {
221→                requireNumeric(fieldName, firstByte);
222→                yield Long.parseLong(parseNumberString(src, pos));
223→            }
224→        };
225→    }
226→
227→    private Object parseVector(byte[] src, int[] pos, FieldType.VectorType vt, String fieldName) {
228→        assert src != null : "src must not be null";
229→        assert pos != null : "pos must not be null";
230→        assert vt != null : "vt must not be null";
231→
232→        expect(src, pos, '[');
233→        skipWhitespace(src, pos);
234→
235→        final int d = vt.dimensions();
236→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
237→            final float[] vec = new float[d];
238→            for (int i = 0; i < d; i++) {
239→                if (i > 0) {
240→                    skipWhitespace(src, pos);
241→                    expect(src, pos, ',');
242→                    skipWhitespace(src, pos);
243→                }
244→                vec[i] = parseFloat(src, pos);
245→            }
246→            skipWhitespace(src, pos);
247→            expect(src, pos, ']');
248→            return vec;
249→        } else {
250→            final short[] vec = new short[d];
251→            for (int i = 0; i < d; i++) {
252→                if (i > 0) {
253→                    skipWhitespace(src, pos);
254→                    expect(src, pos, ',');
255→                    skipWhitespace(src, pos);
256→                }
257→                vec[i] = Float16.fromFloat(parseFloat(src, pos));
258→            }
259→            skipWhitespace(src, pos);
260→            expect(src, pos, ']');
261→            return vec;
262→        }
263→    }
264→
265→    private float parseFloat(byte[] src, int[] pos) {
266→        final int start = pos[0];
267→        while (pos[0] < src.length) {
268→            final byte b = src[pos[0]];
269→            if (b == ',' || b == ']' || b == ' ' || b == '\n' || b == '\r' || b == '\t') {
270→                break;
271→            }
272→            pos[0]++;
273→        }
274→        return Float.parseFloat(new String(src, start, pos[0] - start,
275→                java.nio.charset.StandardCharsets.US_ASCII));
276→    }
277→
278→    private Object[] parseArray(byte[] src, int[] pos, FieldType.ArrayType at, String fieldName,
279→            JlsmSchema parentSchema) {
280→        assert src != null : "src must not be null";
281→        assert pos != null : "pos must not be null";
282→        assert at != null : "at must not be null";
283→
284→        expect(src, pos, '[');
285→        skipWhitespace(src, pos);
286→
287→        if (pos[0] < src.length && src[pos[0]] == ']') {
288→            pos[0]++;
289→            return new Object[0];
290→        }
291→
292→        final ArrayList<Object> list = new ArrayList<>();
293→        boolean first = true;
294→
295→        while (pos[0] < src.length) {
296→            if (!first) {
297→                skipWhitespace(src, pos);
298→                expect(src, pos, ',');
299→                skipWhitespace(src, pos);
300→            }
301→            first = false;
302→
303→            if (pos[0] < src.length && src[pos[0]] == ']') {
304→                break;
305→            }
306→
307→            list.add(parseValue(src, pos, at.elementType(), fieldName + "[]", parentSchema));
308→
309→            skipWhitespace(src, pos);
310→            if (pos[0] < src.length && src[pos[0]] == ']') {
311→                break;
312→            }
313→        }
314→
315→        expect(src, pos, ']');
316→        return list.toArray();
317→    }
318→
319→    // -------------------------------------------------------------------------
320→    // Primitive value parsers
321→    // -------------------------------------------------------------------------
322→
323→    /**
324→     * Parses a JSON string value (surrounded by double-quotes). Uses SIMD acceleration via
325→     * {@link ByteVector} to scan for quote and backslash bytes in bulk.
326→     */
327→    private String parseString(byte[] src, int[] pos) {
328→        assert src != null : "src must not be null";
329→        assert pos != null : "pos must not be null";
330→
331→        expect(src, pos, '"');
332→
333→        final StringBuilder sb = new StringBuilder();
334→        int i = pos[0];
335→
336→        while (i < src.length) {
337→            // SIMD scan to the next quote or backslash
338→            final int delim = scanToStringEnd(src, i);
339→
340→            // Append the safe segment
341→            if (delim > i) {
342→                sb.append(new String(src, i, delim - i, StandardCharsets.UTF_8));
343→            }
344→
345→            if (delim >= src.length) {
346→                throw new IllegalArgumentException("Unterminated string in JSON");
347→            }
348→
349→            final byte b = src[delim];
350→            if (b == '"') {
351→                // End of string
352→                i = delim + 1;
353→                break;
354→            }
355→
356→            // Backslash escape
357→            if (delim + 1 >= src.length) {
358→                throw new IllegalArgumentException("Truncated escape sequence in JSON string");
359→            }
360→            final byte escape = src[delim + 1];
361→            switch (escape) {
362→                case '"' -> sb.append('"');
363→                case '\\' -> sb.append('\\');
364→                case '/' -> sb.append('/');
365→                case 'n' -> sb.append('\n');
366→                case 'r' -> sb.append('\r');
367→                case 't' -> sb.append('\t');
368→                case 'b' -> sb.append('\b');
369→                case 'f' -> sb.append('\f');
370→                case 'u' -> {
371→                    if (delim + 5 >= src.length) {
372→                        throw new IllegalArgumentException(
373→                                "Truncated \\u escape sequence in JSON string");
374→                    }
375→                    final String hex = new String(src, delim + 2, 4, StandardCharsets.US_ASCII);
376→                    try {
377→                        final int codePoint = Integer.parseInt(hex, 16);
378→                        sb.append((char) codePoint);
379→                    } catch (NumberFormatException e) {
380→                        throw new IllegalArgumentException("Invalid \\u escape sequence: \\u" + hex,
381→                                e);
382→                    }
383→                    i = delim + 6;
384→                    continue;
385→                }
386→                default -> throw new IllegalArgumentException(
387→                        "Unknown escape sequence: \\" + (char) escape);
388→            }
389→            i = delim + 2;
390→        }
391→
392→        pos[0] = i;
393→        return sb.toString();
394→    }
395→
396→    /**
397→     * Scans byte array from {@code pos} to find the next {@code "} or {@code \} byte using SIMD
398→     * acceleration via {@link ByteVector}.
399→     *
400→     * @param src the byte array
401→     * @param pos the starting position
402→     * @return the index of the first {@code "} or {@code \}, or {@code src.length} if not found
403→     */
404→    private static int scanToStringEnd(byte[] src, int pos) {
405→        assert src != null : "src must not be null";
406→        assert pos >= 0 : "pos must not be negative";
407→
408→        final int len = BSPECIES.length();
409→        final ByteVector delimiters = ByteVector.broadcast(BSPECIES, (byte) '"');
410→        final ByteVector escapes = ByteVector.broadcast(BSPECIES, (byte) '\\');
411→
412→        while (pos + len <= src.length) {
413→            final ByteVector chunk = ByteVector.fromArray(BSPECIES, src, pos);
414→            final var hit = chunk.eq(delimiters).or(chunk.eq(escapes));
415→            if (hit.anyTrue()) {
416→                return pos + hit.firstTrue();
417→            }
418→            pos += len;
419→        }
420→
421→        // Scalar remainder
422→        while (pos < src.length) {
423→            final byte b = src[pos];
424→            if (b == '"' || b == '\\') {
425→                return pos;
426→            }
427→            pos++;
428→        }
429→
430→        return pos; // not found — caller handles unterminated string
431→    }
432→
433→    private boolean parseBoolean(byte[] src, int[] pos) {
434→        assert src != null : "src must not be null";
435→        assert pos != null : "pos must not be null";
436→
437→        if (src[pos[0]] == 't') {
438→            parseLiteral(src, pos, "true");
439→            return true;
440→        } else {
441→            parseLiteral(src, pos, "false");
442→            return false;
443→        }
444→    }
445→
446→    /**
447→     * Parses a JSON number token and returns it as a String for further type conversion.
448→     *
449→     * @param src the source bytes
450→     * @param pos the current position (updated on return)
451→     * @return the raw number string
452→     */
453→    private static String parseNumberString(byte[] src, int[] pos) {
454→        assert src != null : "src must not be null";
455→        assert pos != null : "pos must not be null";
456→
457→        final int start = pos[0];
458→        int i = start;
459→
460→        // Optional leading minus
461→        if (i < src.length && src[i] == '-') {
462→            i++;
463→        }
464→
465→        // Integer digits
466→        while (i < src.length && src[i] >= '0' && src[i] <= '9') {
467→            i++;
468→        }
469→
470→        // Optional fractional part
471→        if (i < src.length && src[i] == '.') {
472→            i++;
473→            while (i < src.length && src[i] >= '0' && src[i] <= '9') {
474→                i++;
475→            }
476→        }
477→
478→        // Optional exponent
479→        if (i < src.length && (src[i] == 'e' || src[i] == 'E')) {
480→            i++;
481→            if (i < src.length && (src[i] == '+' || src[i] == '-')) {
482→                i++;
483→            }
484→            while (i < src.length && src[i] >= '0' && src[i] <= '9') {
485→                i++;
486→            }
487→        }
488→
489→        if (i == start) {
490→            throw new IllegalArgumentException("Expected a number at position " + start);
491→        }
492→
493→        pos[0] = i;
494→        return new String(src, start, i - start, StandardCharsets.US_ASCII);
495→    }
