497→    // -------------------------------------------------------------------------
498→    // Skip unknown values
499→    // -------------------------------------------------------------------------
500→
501→    private void skipValue(byte[] src, int[] pos) {
502→        assert src != null : "src must not be null";
503→        assert pos != null : "pos must not be null";
504→
505→        skipWhitespace(src, pos);
506→
507→        if (pos[0] >= src.length) {
508→            throw new IllegalArgumentException("Unexpected end of JSON while skipping value");
509→        }
510→
511→        final byte b = src[pos[0]];
512→        if (b == '"') {
513→            parseString(src, pos);
514→        } else if (b == '{') {
515→            skipObject(src, pos);
516→        } else if (b == '[') {
517→            skipArray(src, pos);
518→        } else if (b == 't') {
519→            parseLiteral(src, pos, "true");
520→        } else if (b == 'f') {
521→            parseLiteral(src, pos, "false");
522→        } else if (b == 'n') {
523→            parseLiteral(src, pos, "null");
524→        } else if (b == '-' || (b >= '0' && b <= '9')) {
525→            parseNumberString(src, pos);
526→        } else {
527→            throw new IllegalArgumentException(
528→                    "Unexpected token '" + (char) b + "' at position " + pos[0]);
529→        }
530→    }
531→
532→    private void skipObject(byte[] src, int[] pos) {
533→        expect(src, pos, '{');
534→        skipWhitespace(src, pos);
535→        if (pos[0] < src.length && src[pos[0]] == '}') {
536→            pos[0]++;
537→            return;
538→        }
539→        boolean first = true;
540→        while (pos[0] < src.length) {
541→            if (!first) {
542→                skipWhitespace(src, pos);
543→                expect(src, pos, ',');
544→            }
545→            first = false;
546→            skipWhitespace(src, pos);
547→            if (pos[0] < src.length && src[pos[0]] == '}') {
548→                break;
549→            }
550→            parseString(src, pos);
551→            skipWhitespace(src, pos);
552→            expect(src, pos, ':');
553→            skipWhitespace(src, pos);
554→            skipValue(src, pos);
555→            skipWhitespace(src, pos);
556→            if (pos[0] < src.length && src[pos[0]] == '}') {
557→                break;
558→            }
559→        }
560→        expect(src, pos, '}');
561→    }
562→
563→    private void skipArray(byte[] src, int[] pos) {
564→        expect(src, pos, '[');
565→        skipWhitespace(src, pos);
566→        if (pos[0] < src.length && src[pos[0]] == ']') {
567→            pos[0]++;
568→            return;
569→        }
570→        boolean first = true;
571→        while (pos[0] < src.length) {
572→            if (!first) {
573→                skipWhitespace(src, pos);
574→                expect(src, pos, ',');
575→                skipWhitespace(src, pos);
576→            }
577→            first = false;
578→            if (pos[0] < src.length && src[pos[0]] == ']') {
579→                break;
580→            }
581→            skipValue(src, pos);
582→            skipWhitespace(src, pos);
583→            if (pos[0] < src.length && src[pos[0]] == ']') {
584→                break;
585→            }
586→        }
587→        expect(src, pos, ']');
588→    }
589→
590→    // -------------------------------------------------------------------------
591→    // Low-level helpers
592→    // -------------------------------------------------------------------------
593→
594→    private static void skipWhitespace(byte[] src, int[] pos) {
595→        assert src != null : "src must not be null";
596→        assert pos != null : "pos must not be null";
597→
598→        int i = pos[0];
599→        while (i < src.length) {
600→            final byte b = src[i];
601→            if (b == ' ' || b == '\t' || b == '\n' || b == '\r') {
602→                i++;
603→            } else {
604→                break;
605→            }
606→        }
607→        pos[0] = i;
608→    }
609→
610→    private static void expect(byte[] src, int[] pos, char expected) {
611→        assert src != null : "src must not be null";
612→        assert pos != null : "pos must not be null";
613→
614→        if (pos[0] >= src.length) {
615→            throw new IllegalArgumentException(
616→                    "Expected '" + expected + "' but reached end of JSON");
617→        }
618→        if (src[pos[0]] != (byte) expected) {
619→            throw new IllegalArgumentException("Expected '" + expected + "' at position " + pos[0]
620→                    + " but got '" + (char) src[pos[0]] + "'");
621→        }
622→        pos[0]++;
623→    }
624→
625→    private static void parseLiteral(byte[] src, int[] pos, String literal) {
626→        assert src != null : "src must not be null";
627→        assert pos != null : "pos must not be null";
628→        assert literal != null : "literal must not be null";
629→
630→        final byte[] litBytes = literal.getBytes(StandardCharsets.US_ASCII);
631→        if (pos[0] + litBytes.length > src.length) {
632→            throw new IllegalArgumentException(
633→                    "Expected '" + literal + "' at position " + pos[0] + " but input is too short");
634→        }
635→        for (int i = 0; i < litBytes.length; i++) {
636→            if (src[pos[0] + i] != litBytes[i]) {
637→                throw new IllegalArgumentException(
638→                        "Expected '" + literal + "' at position " + pos[0]);
639→            }
640→        }
641→        pos[0] += litBytes.length;
642→    }
643→
644→    private static void requireNumeric(String fieldName, byte firstByte) {
645→        if (firstByte != '-' && (firstByte < '0' || firstByte > '9')) {
646→            throw new IllegalArgumentException(
647→                    "Field '" + fieldName + "' expects a numeric value, got token starting with '"
648→                            + (char) firstByte + "'");
649→        }
650→    }
651→}
