  9→/**
 10→ * Serializes a {@link JlsmDocument} to a YAML block-style string.
 11→ *
 12→ * <p>
 13→ * Thread-safe for concurrent use; each {@link #write} call creates its own {@link StringBuilder}.
 14→ * Output uses block mappings and block sequences (no flow style).
 15→ */
 16→public final class YamlWriter {
 17→
 18→    /** Characters that require quoting a YAML string value. */
 19→    private static final String SPECIAL_CHARS = "#:{}[]\n\r\t,&*?|>!%@`";
 20→
 21→    /** Creates a new YamlWriter. */
 22→    public YamlWriter() {
 23→    }
 24→
 25→    /**
 26→     * Serializes the document to YAML block style.
 27→     *
 28→     * @param doc the document to serialize; must not be null
 29→     * @return a YAML string (no trailing newline)
 30→     */
 31→    public String write(JlsmDocument doc) {
 32→        assert doc != null : "doc must not be null";
 33→
 34→        final StringBuilder sb = new StringBuilder(256);
 35→        writeDocument(doc, sb, 0);
 36→        return sb.toString();
 37→    }
 38→
 39→    // -------------------------------------------------------------------------
 40→    // Private helpers
 41→    // -------------------------------------------------------------------------
 42→
 43→    private void writeDocument(JlsmDocument doc, StringBuilder sb, int depth) {
 44→        assert doc != null : "doc must not be null";
 45→        assert sb != null : "sb must not be null";
 46→        assert depth >= 0 : "depth must not be negative";
 47→
 48→        final JlsmSchema schema = doc.schema();
 49→        final Object[] values = DocumentAccess.get().values(doc);
 50→
 51→        for (int i = 0; i < schema.fields().size(); i++) {
 52→            final FieldDefinition fd = schema.fields().get(i);
 53→            final Object value = values[i];
 54→
 55→            if (i > 0) {
 56→                sb.append('\n');
 57→            }
 58→
 59→            appendIndent(sb, depth);
 60→            sb.append(fd.name());
 61→            sb.append(':');
 62→
 63→            writeValue(fd.type(), value, sb, depth);
 64→        }
 65→    }
 66→
 67→    private void writeValue(FieldType type, Object value, StringBuilder sb, int depth) {
 68→        assert sb != null : "sb must not be null";
 69→
 70→        if (value == null) {
 71→            sb.append(" null");
 72→            return;
 73→        }
 74→
 75→        switch (type) {
 76→            case FieldType.Primitive p -> writePrimitive(p, value, sb);
 77→            case FieldType.ArrayType at -> writeArray(at, (Object[]) value, sb, depth);
 78→            case FieldType.VectorType vt -> writeVector(vt, value, sb, depth);
 79→            case FieldType.ObjectType _ -> {
 80→                sb.append('\n');
 81→                writeDocument((JlsmDocument) value, sb, depth + 1);
 82→            }
 83→        }
 84→    }
 85→
 86→    private void writePrimitive(FieldType.Primitive p, Object value, StringBuilder sb) {
 87→        assert p != null : "p must not be null";
 88→        assert value != null : "value must not be null";
 89→        assert sb != null : "sb must not be null";
 90→
 91→        sb.append(' ');
 92→        switch (p) {
 93→            case STRING -> writeYamlString((String) value, sb);
 94→            case INT8 -> sb.append((Byte) value);
 95→            case INT16 -> sb.append((Short) value);
 96→            case INT32 -> sb.append((Integer) value);
 97→            case INT64 -> sb.append((Long) value);
 98→            case FLOAT16 -> {
 99→                final float f = Float16.toFloat((Short) value);
100→                writeYamlFloat(f, sb);
101→            }
102→            case FLOAT32 -> writeYamlFloat((Float) value, sb);
103→            case FLOAT64 -> writeYamlDouble((Double) value, sb);
104→            case BOOLEAN -> sb.append((Boolean) value ? "true" : "false");
105→            case TIMESTAMP -> sb.append((Long) value);
106→        }
107→    }
108→
109→    private void writeArray(FieldType.ArrayType at, Object[] elements, StringBuilder sb,
110→            int depth) {
111→        assert at != null : "at must not be null";
112→        assert elements != null : "elements must not be null";
113→        assert sb != null : "sb must not be null";
114→
115→        for (int i = 0; i < elements.length; i++) {
116→            sb.append('\n');
117→            appendIndent(sb, depth);
118→            sb.append('-');
119→            writeArrayElement(at.elementType(), elements[i], sb, depth);
120→        }
121→    }
122→
123→    private void writeVector(FieldType.VectorType vt, Object value, StringBuilder sb, int depth) {
124→        assert vt != null : "vt must not be null";
125→        assert value != null : "value must not be null";
126→        assert sb != null : "sb must not be null";
127→
128→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
129→            final float[] vec = (float[]) value;
130→            for (int i = 0; i < vec.length; i++) {
131→                sb.append('\n');
132→                appendIndent(sb, depth);
133→                sb.append("- ");
134→                writeYamlFloat(vec[i], sb);
135→            }
136→        } else {
137→            final short[] vec = (short[]) value;
138→            for (int i = 0; i < vec.length; i++) {
139→                sb.append('\n');
140→                appendIndent(sb, depth);
141→                sb.append("- ");
142→                writeYamlFloat(Float16.toFloat(vec[i]), sb);
143→            }
144→        }
145→    }
146→
147→    private void writeArrayElement(FieldType elementType, Object value, StringBuilder sb,
148→            int depth) {
149→        assert sb != null : "sb must not be null";
150→
151→        if (value == null) {
152→            sb.append(" null");
153→            return;
154→        }
155→
156→        switch (elementType) {
157→            case FieldType.Primitive p -> writePrimitive(p, value, sb);
158→            case FieldType.ArrayType _ ->
159→                throw new UnsupportedOperationException("Nested arrays not supported in YAML");
160→            case FieldType.VectorType _ ->
161→                throw new UnsupportedOperationException("Nested vectors not supported in YAML");
162→            case FieldType.ObjectType _ -> {
163→                sb.append('\n');
164→                writeDocument((JlsmDocument) value, sb, depth + 1);
165→            }
166→        }
167→    }
