169→    private static void writeYamlFloat(float f, StringBuilder sb) {
170→        assert sb != null : "sb must not be null";
171→        if (!Float.isFinite(f)) {
172→            sb.append("null");
173→        } else {
174→            sb.append(f);
175→        }
176→    }
177→
178→    private static void writeYamlDouble(double d, StringBuilder sb) {
179→        assert sb != null : "sb must not be null";
180→        if (!Double.isFinite(d)) {
181→            sb.append("null");
182→        } else {
183→            sb.append(d);
184→        }
185→    }
