187→    /**
188→     * Writes a YAML string value. Quotes with double-quotes if the string is empty, looks like a
189→     * YAML keyword (true/false/null), looks like a number, or contains special characters.
190→     */
191→    private static void writeYamlString(String s, StringBuilder sb) {
192→        assert s != null : "s must not be null";
193→        assert sb != null : "sb must not be null";
194→
195→        if (needsQuoting(s)) {
196→            sb.append('"');
197→            for (int i = 0; i < s.length(); i++) {
198→                final char c = s.charAt(i);
199→                switch (c) {
200→                    case '"' -> sb.append("\\\"");
201→                    case '\\' -> sb.append("\\\\");
202→                    case '\n' -> sb.append("\\n");
203→                    case '\r' -> sb.append("\\r");
204→                    case '\t' -> sb.append("\\t");
205→                    default -> sb.append(c);
206→                }
207→            }
208→            sb.append('"');
209→        } else {
210→            sb.append(s);
211→        }
212→    }
