214→    /**
215→     * Determines whether a YAML scalar string needs to be quoted.
216→     */
217→    private static boolean needsQuoting(String s) {
218→        assert s != null : "s must not be null";
219→
220→        // Empty string must be quoted
221→        if (s.isEmpty()) {
222→            return true;
223→        }
224→
225→        // YAML keywords
226→        if ("true".equals(s) || "false".equals(s) || "null".equals(s) || "True".equals(s)
227→                || "False".equals(s) || "Null".equals(s) || "TRUE".equals(s) || "FALSE".equals(s)
228→                || "NULL".equals(s) || "yes".equals(s) || "no".equals(s) || "Yes".equals(s)
229→                || "No".equals(s) || "YES".equals(s) || "NO".equals(s) || "on".equals(s)
230→                || "off".equals(s) || "On".equals(s) || "Off".equals(s) || "ON".equals(s)
231→                || "OFF".equals(s)) {
232→            return true;
233→        }
234→
235→        // Check if it looks like a number
236→        if (looksLikeNumber(s)) {
237→            return true;
238→        }
239→
240→        // Leading/trailing whitespace
241→        if (s.charAt(0) == ' ' || s.charAt(s.length() - 1) == ' ') {
242→            return true;
243→        }
244→
245→        // Contains special characters
246→        for (int i = 0; i < s.length(); i++) {
247→            if (SPECIAL_CHARS.indexOf(s.charAt(i)) >= 0) {
248→                return true;
249→            }
250→        }
251→
252→        return false;
253→    }
