261→        int i = 0;
262→        if (s.charAt(0) == '-' || s.charAt(0) == '+') {
263→            i = 1;
264→        }
265→        if (i >= s.length()) {
266→            return false;
267→        }
268→
269→        boolean hasDigit = false;
270→        while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
271→            hasDigit = true;
272→            i++;
273→        }
274→
275→        if (i < s.length() && s.charAt(i) == '.') {
276→            i++;
277→            while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
278→                hasDigit = true;
279→                i++;
280→            }
281→        }
282→
283→        if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
284→            i++;
285→            if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
286→                i++;
287→            }
288→            while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
289→                i++;
290→            }
291→        }
292→
293→        return hasDigit && i == s.length();
294→    }
295→
296→    private static void appendIndent(StringBuilder sb, int depth) {
297→        assert sb != null : "sb must not be null";
298→        assert depth >= 0 : "depth must not be negative";
299→
300→        final int spaces = 2 * depth;
301→        for (int i = 0; i < spaces; i++) {
302→            sb.append(' ');
303→        }
304→    }
305→}
