  1→package jlsm.table.internal;
  2→
  3→import java.util.ArrayList;
  4→import java.util.List;
  5→
  6→import jlsm.table.FieldDefinition;
  7→import jlsm.table.FieldType;
  8→import jlsm.table.Float16;
  9→import jlsm.table.JlsmDocument;
 10→import jlsm.table.JlsmSchema;
 11→
 12→/**
 13→ * Line-oriented state-machine parser for the restricted YAML subset produced by {@link YamlWriter}.
 14→ *
 15→ * <p>
 16→ * Supports block mappings and block sequences only. Parsing is schema-guided: the schema determines
 17→ * the expected type of each field value.
 18→ *
 19→ * <p>
 20→ * Thread-safe for concurrent use; each {@link #parse} call operates on local state only.
 21→ */
 22→public final class YamlParser {
 23→
 24→    /** Creates a new YamlParser. */
 25→    public YamlParser() {
 26→    }
 27→
 28→    /**
 29→     * Parses a YAML string into a {@link JlsmDocument}.
 30→     *
 31→     * @param yaml the YAML string; must not be null
 32→     * @param schema the target schema; must not be null
 33→     * @return a new JlsmDocument
 34→     * @throws IllegalArgumentException if the YAML is malformed or a field type does not match
 35→     */
 36→    public JlsmDocument parse(String yaml, JlsmSchema schema) {
 37→        if (yaml == null) {
 38→            throw new IllegalArgumentException("yaml must not be null");
 39→        }
 40→        if (schema == null) {
 41→            throw new IllegalArgumentException("schema must not be null");
 42→        }
 43→
 44→        final List<String> lines = splitLines(yaml);
 45→        final int[] lineRef = { 0 };
 46→        return parseMapping(lines, lineRef, 0, schema);
 47→    }
 48→
 49→    // -------------------------------------------------------------------------
 50→    // Mapping parsing
 51→    // -------------------------------------------------------------------------
 52→
 53→    /**
 54→     * Parses a YAML block mapping at the given indent level.
 55→     *
 56→     * @param lines all lines
 57→     * @param lineRef mutable line index
 58→     * @param expectedIndent the indent level for keys in this mapping
 59→     * @param schema the schema describing expected fields
 60→     * @return a new JlsmDocument
 61→     */
 62→    private JlsmDocument parseMapping(List<String> lines, int[] lineRef, int expectedIndent,
 63→            JlsmSchema schema) {
 64→        assert lines != null : "lines must not be null";
 65→        assert lineRef != null : "lineRef must not be null";
 66→        assert schema != null : "schema must not be null";
 67→
 68→        final Object[] values = new Object[schema.fields().size()];
 69→
 70→        while (lineRef[0] < lines.size()) {
 71→            final String line = lines.get(lineRef[0]);
 72→
 73→            // Skip blank lines
 74→            if (line.isBlank()) {
 75→                lineRef[0]++;
 76→                continue;
 77→            }
 78→
 79→            final int indent = measureIndent(line);
 80→
 81→            // If indent is less than expected, we've exited this mapping
 82→            if (indent < expectedIndent) {
 83→                break;
 84→            }
 85→
 86→            // If indent is greater than expected, it's a formatting error at this level
 87→            if (indent > expectedIndent) {
 88→                throw new IllegalArgumentException("Unexpected indent at line " + (lineRef[0] + 1)
 89→                        + ": expected " + expectedIndent + " spaces but got " + indent);
 90→            }
 91→
 92→            // Parse key: value
 93→            final String trimmed = line.substring(indent);
 94→            final int colonIdx = trimmed.indexOf(':');
 95→            if (colonIdx < 0) {
 96→                throw new IllegalArgumentException(
 97→                        "Expected 'key: value' at line " + (lineRef[0] + 1) + ": " + line);
 98→            }
 99→
100→            final String key = trimmed.substring(0, colonIdx);
101→            final String afterColon = trimmed.substring(colonIdx + 1);
102→
103→            final int fieldIdx = schema.fieldIndex(key);
104→            if (fieldIdx < 0) {
105→                // Unknown field — skip this line and any nested content
106→                lineRef[0]++;
107→                skipNestedContent(lines, lineRef, expectedIndent);
108→                continue;
109→            }
110→
111→            final FieldDefinition fd = schema.fields().get(fieldIdx);
112→            lineRef[0]++;
113→
114→            values[fieldIdx] = parseFieldValue(lines, lineRef, expectedIndent, afterColon, fd);
115→        }
116→
117→        return DocumentAccess.get().create(schema, values);
118→    }
119→
120→    /**
121→     * Parses the value for a field, which may be inline (after the colon) or in subsequent indented
122→     * lines (for objects and arrays).
123→     */
124→    private Object parseFieldValue(List<String> lines, int[] lineRef, int mappingIndent,
125→            String afterColon, FieldDefinition fd) {
126→        assert lines != null : "lines must not be null";
127→        assert lineRef != null : "lineRef must not be null";
128→        assert fd != null : "fd must not be null";
129→
130→        final String valuePart = afterColon.trim();
131→
132→        return switch (fd.type()) {
133→            case FieldType.Primitive p -> {
134→                if (valuePart.isEmpty()) {
135→                    throw new IllegalArgumentException("Expected value for primitive field '"
136→                            + fd.name() + "' at line " + lineRef[0]);
137→                }
138→                yield parsePrimitiveValue(valuePart, p, fd.name());
139→            }
140→            case FieldType.ArrayType at -> {
141→                // Value should be empty (array items follow on next lines)
142→                if (!valuePart.isEmpty() && !"null".equals(valuePart)) {
143→                    throw new IllegalArgumentException("Expected block sequence for array field '"
144→                            + fd.name() + "' at line " + lineRef[0]);
145→                }
146→                if ("null".equals(valuePart)) {
147→                    yield null;
148→                }
149→                yield parseBlockSequence(lines, lineRef, mappingIndent, at);
150→            }
151→            case FieldType.VectorType vt -> {
152→                if ("null".equals(valuePart)) {
153→                    yield null;
154→                }
155→                yield parseVectorSequence(lines, lineRef, mappingIndent, vt);
156→            }
157→            case FieldType.ObjectType ot -> {
158→                if ("null".equals(valuePart)) {
159→                    yield null;
160→                }
161→                // Nested mapping follows on indented lines
162→                final JlsmSchema subSchema = ot.toSchema(fd.name(), 1);
163→                yield parseMapping(lines, lineRef, mappingIndent + 2, subSchema);
164→            }
165→        };
166→    }
167→
168→    // -------------------------------------------------------------------------
169→    // Block sequence parsing
170→    // -------------------------------------------------------------------------
171→
172→    /**
173→     * Parses a YAML block sequence (lines starting with "- ") at indent = mappingIndent.
174→     */
175→    private Object parseVectorSequence(List<String> lines, int[] lineRef, int mappingIndent,
176→            FieldType.VectorType vt) {
177→        final int d = vt.dimensions();
178→        final int itemIndent = mappingIndent + 2;
179→
180→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
181→            final float[] vec = new float[d];
182→            for (int i = 0; i < d; i++) {
183→                lineRef[0]++;
184→                if (lineRef[0] >= lines.size()) {
185→                    throw new IllegalArgumentException(
186→                            "Expected " + d + " vector elements but only got " + i);
187→                }
188→                final String line = lines.get(lineRef[0]);
189→                final String trimmed = line.stripLeading();
190→                if (!trimmed.startsWith("- ")) {
191→                    throw new IllegalArgumentException(
192→                            "Expected YAML list item for vector at line " + lineRef[0]);
193→                }
194→                vec[i] = Float.parseFloat(trimmed.substring(2).trim());
195→            }
196→            return vec;
197→        } else {
198→            final short[] vec = new short[d];
199→            for (int i = 0; i < d; i++) {
200→                lineRef[0]++;
201→                if (lineRef[0] >= lines.size()) {
202→                    throw new IllegalArgumentException(
203→                            "Expected " + d + " vector elements but only got " + i);
204→                }
205→                final String line = lines.get(lineRef[0]);
206→                final String trimmed = line.stripLeading();
207→                if (!trimmed.startsWith("- ")) {
208→                    throw new IllegalArgumentException(
209→                            "Expected YAML list item for vector at line " + lineRef[0]);
210→                }
211→                vec[i] = Float16.fromFloat(Float.parseFloat(trimmed.substring(2).trim()));
212→            }
213→            return vec;
214→        }
215→    }
216→
217→    private Object[] parseBlockSequence(List<String> lines, int[] lineRef, int mappingIndent,
218→            FieldType.ArrayType at) {
219→        assert lines != null : "lines must not be null";
220→        assert lineRef != null : "lineRef must not be null";
221→        assert at != null : "at must not be null";
222→
223→        final ArrayList<Object> elements = new ArrayList<>();
224→
225→        while (lineRef[0] < lines.size()) {
226→            final String line = lines.get(lineRef[0]);
227→
228→            if (line.isBlank()) {
229→                lineRef[0]++;
230→                continue;
231→            }
232→
233→            final int indent = measureIndent(line);
234→
235→            // Sequence items are at the same indent as the parent mapping key
236→            if (indent != mappingIndent) {
237→                break;
238→            }
239→
240→            final String trimmed = line.substring(indent);
241→            if (!trimmed.startsWith("- ") && !trimmed.equals("-")) {
242→                break;
243→            }
244→
245→            final String itemValue = trimmed.length() > 2 ? trimmed.substring(2).trim() : "";
246→            lineRef[0]++;
247→
248→            if (at.elementType() instanceof FieldType.Primitive p) {
249→                elements.add(parsePrimitiveValue(itemValue, p, "array element"));
250→            } else if (at.elementType() instanceof FieldType.ObjectType ot) {
251→                if ("null".equals(itemValue)) {
252→                    elements.add(null);
253→                } else {
254→                    final JlsmSchema subSchema = ot.toSchema("element", 1);
255→                    elements.add(parseMapping(lines, lineRef, indent + 2, subSchema));
256→                }
257→            } else {
258→                throw new UnsupportedOperationException("Nested arrays not supported in YAML");
259→            }
260→        }
261→
262→        return elements.toArray();
263→    }
264→
265→    // -------------------------------------------------------------------------
266→    // Primitive value parsing
267→    // -------------------------------------------------------------------------
268→
269→    /**
270→     * Parses a scalar string value into the appropriate Java type based on the primitive type.
271→     */
272→    private Object parsePrimitiveValue(String raw, FieldType.Primitive p, String fieldName) {
273→        assert raw != null : "raw must not be null";
274→        assert p != null : "p must not be null";
275→
276→        if ("null".equals(raw)) {
277→            return null;
278→        }
279→
280→        try {
281→            return switch (p) {
282→                case STRING -> unquoteString(raw);
283→                case INT8 -> Byte.parseByte(raw);
284→                case INT16 -> Short.parseShort(raw);
285→                case INT32 -> Integer.parseInt(raw);
286→                case INT64 -> Long.parseLong(raw);
287→                case FLOAT16 -> Float16.fromFloat(Float.parseFloat(raw));
288→                case FLOAT32 -> Float.parseFloat(raw);
289→                case FLOAT64 -> Double.parseDouble(raw);
290→                case BOOLEAN -> parseBoolean(raw, fieldName);
291→                case TIMESTAMP -> Long.parseLong(raw);
292→            };
293→        } catch (NumberFormatException e) {
294→            throw new IllegalArgumentException(
295→                    "Field '" + fieldName + "' cannot parse value '" + raw + "' as " + p, e);
296→        }
297→    }
298→
299→    /**
300→     * Parses a boolean value. Only accepts "true" and "false".
301→     */
302→    private static Boolean parseBoolean(String raw, String fieldName) {
303→        assert raw != null : "raw must not be null";
304→
305→        if ("true".equals(raw)) {
306→            return Boolean.TRUE;
307→        }
308→        if ("false".equals(raw)) {
309→            return Boolean.FALSE;
310→        }
311→        throw new IllegalArgumentException(
312→                "Field '" + fieldName + "' expects boolean (true/false), got '" + raw + "'");
313→    }
314→
315→    /**
316→     * Unquotes a YAML string value. If the value is surrounded by double quotes, strips them and
317→     * unescapes. Otherwise returns as-is.
318→     */
319→    private static String unquoteString(String raw) {
320→        assert raw != null : "raw must not be null";
321→
322→        if (raw.length() >= 2 && raw.charAt(0) == '"' && raw.charAt(raw.length() - 1) == '"') {
323→            final String inner = raw.substring(1, raw.length() - 1);
324→            return unescapeYamlString(inner);
325→        }
326→        return raw;
327→    }
328→
329→    /**
330→     * Unescapes a double-quoted YAML string (backslash sequences).
331→     */
332→    private static String unescapeYamlString(String s) {
333→        assert s != null : "s must not be null";
334→
335→        final StringBuilder sb = new StringBuilder(s.length());
336→        int i = 0;
337→        while (i < s.length()) {
338→            final char c = s.charAt(i);
339→            if (c == '\\' && i + 1 < s.length()) {
340→                final char next = s.charAt(i + 1);
341→                switch (next) {
342→                    case '"' -> sb.append('"');
343→                    case '\\' -> sb.append('\\');
344→                    case 'n' -> sb.append('\n');
345→                    case 'r' -> sb.append('\r');
346→                    case 't' -> sb.append('\t');
347→                    default -> {
348→                        sb.append(c);
349→                        sb.append(next);
350→                    }
351→                }
352→                i += 2;
353→            } else {
354→                sb.append(c);
355→                i++;
356→            }
357→        }
358→        return sb.toString();
359→    }
360→
361→    // -------------------------------------------------------------------------
362→    // Utility helpers
363→    // -------------------------------------------------------------------------
364→
365→    /**
366→     * Splits a string into lines. Handles \n, \r\n, and \r.
367→     */
368→    private static List<String> splitLines(String s) {
369→        assert s != null : "s must not be null";
370→
371→        final ArrayList<String> lines = new ArrayList<>();
372→        int start = 0;
373→        final int len = s.length();
374→
375→        int i = 0;
376→        while (i < len) {
377→            if (s.charAt(i) == '\n') {
378→                lines.add(s.substring(start, i));
379→                start = i + 1;
380→                i++;
381→            } else if (s.charAt(i) == '\r') {
382→                lines.add(s.substring(start, i));
383→                i++;
384→                if (i < len && s.charAt(i) == '\n') {
385→                    i++;
386→                }
387→                start = i;
388→            } else {
389→                i++;
390→            }
391→        }
392→
393→        // Last segment (even if empty)
394→        if (start <= len) {
395→            final String last = s.substring(start);
396→            if (!last.isEmpty()) {
397→                lines.add(last);
398→            }
399→        }
400→
401→        return lines;
402→    }
403→
404→    /**
405→     * Measures the number of leading spaces on a line.
406→     */
407→    private static int measureIndent(String line) {
408→        assert line != null : "line must not be null";
409→
410→        int count = 0;
411→        while (count < line.length() && line.charAt(count) == ' ') {
412→            count++;
413→        }
414→        return count;
415→    }
416→
417→    /**
418→     * Skips lines that are nested deeper than the given indent level.
419→     */
420→    private static void skipNestedContent(List<String> lines, int[] lineRef, int parentIndent) {
421→        assert lines != null : "lines must not be null";
422→        assert lineRef != null : "lineRef must not be null";
423→
424→        while (lineRef[0] < lines.size()) {
425→            final String line = lines.get(lineRef[0]);
426→            if (line.isBlank()) {
427→                lineRef[0]++;
428→                continue;
429→            }
430→            final int indent = measureIndent(line);
431→            if (indent <= parentIndent) {
432→                break;
433→            }
434→            lineRef[0]++;
435→        }
436→    }
437→}
