        FieldType.VectorType vt) {
    final int d = vt.dimensions();
    final int itemIndent = mappingIndent + 2;

    if (vt.elementType() == FieldType.Primitive.FLOAT32) {
        final float[] vec = new float[d];
        for (int i = 0; i < d; i++) {
